window.CHAPTERS=window.CHAPTERS||{};window.CHAPTERS["ch03"]={"id": "ch03", "title": "第三章 序列比对原理", "sub": "陈铭《生物信息学》第三版 · 科学出版社", "sub2": "复试生物信息学 · 逐章详解", "modules": [{"i": 0, "name": "第三章 序列比对原理", "slides": [{"i": 0, "sec": "第一节 序列比对相关概念", "title": "序列比对的定义与生物学意义", "notes": "序列比对（sequence alignment）是运用特定数学模型或算法，找出两个或多个序列之间的最大匹配碱基或残基数，反映序列间相似性关系及生物学特征。它是序列分析和数据库搜索的基础，可用于寻找保守基序、判定同源性、预测新基因功能。比对结果反映算法在多大程度上提供序列间相似性关系。双序列比对比较两条序列的相似区域和保守位点，寻找分子进化关系；多序列比对寻找共同保守区域、位点和模式，探索共同功能的序列模式。比对还可将蛋白质序列与核酸序列比较以探索表达框架，或与三维结构蛋白质比较获得结构折叠信息。", "page": 40, "level": "掌握", "img": "assets/img/ch03/p040.jpg", "anim": null, "fig": null, "points": ["按比对序列数量分为双序列比对和多序列比对。", "双序列比对按比对范围分为全局比对和局部比对。", "全局比对对给定序列全长进行比较，引入空位使全长都得到比较，适用于高度同源序列的优化，如以已知三维结构同源序列为基础进行结构预测。", "局部比对仅获得特定序列在数据库中配对最好的亚区，考虑序列片段之间的相似性。"], "check": {"q": "关于序列比对的定义与生物学意义，下列说法正确的是？", "o": ["A. 序列比对只能用于比较两条序列，不能用于数据库搜索", "B. 序列比对是运用特定数学模型或算法找出序列间最大匹配碱基或残基数，是序列分析和数据库搜索的基础", "C. 序列比对结果一定能够证明序列之间具有同源性", "D. 多序列比对主要用于比较两条序列的分子进化关系"], "a": "B", "e": "序列比对是运用特定数学模型或算法，找出两个或多个序列之间的最大匹配碱基或残基数，反映序列间相似性关系及生物学特征，是序列分析和数据库搜索的基础。"}, "cards": [{"front": "什么是序列比对？其生物学意义是什么？", "back": "序列比对是运用特定数学模型或算法，找出两个或多个序列之间的最大匹配碱基或残基数，反映序列间相似性关系及生物学特征。它是序列分析和数据库搜索的基础，可用于寻找保守基序、判定同源性、预测新基因功能。", "mnemonic": "比对找相似，保守同源功能", "useImg": false}, {"front": "双序列比对与多序列比对的主要区别是什么？", "back": "双序列比对比较两条序列的相似区域和保守位点，寻找分子进化关系；多序列比对寻找共同保守区域、位点和模式，探索共同功能。", "mnemonic": "双比找进化，多比找保守", "useImg": false}, {"front": "全局比对和局部比对有何不同？", "back": "全局比对考虑序列的全局相似性，对给定序列全长进行比较，引入空位使全长都得到比较，适用于高度同源序列的优化；局部比对仅获得特定序列在数据库中配对最好的亚区，考虑序列片段之间的相似性。", "mnemonic": "全局全长，局部亚区", "useImg": false}]}, {"i": 1, "sec": "第一节 序列比对相关概念", "title": "序列比对类型：双序列与多序列、全局与局部", "notes": "从比对序列数量分为双序列比对和多序列比对。双序列比对从比对范围又分为全局比对（global alignment）和局部比对（local alignment）。全局比对考虑序列的全局相似性，对给定序列全长进行比较，引入空位使全长都得到比较，适用于高度同源序列的优化，如以已知三维结构同源序列为基础进行结构预测。局部比对仅获得特定序列在数据库中配对最好的亚区，考虑序列片段之间的相似性。双序列比对通过字符匹配和替换、插入和删除字符使两条序列长度相同，并使编辑距离尽可能小。", "page": 40, "level": "掌握", "img": "assets/img/ch03/p040.jpg", "anim": null, "fig": null, "points": ["按比对序列数量分为双序列比对和多序列比对。", "双序列比对按比对范围分为全局比对和局部比对。", "全局比对对给定序列全长进行比较，引入空位使全长都得到比较，适用于高度同源序列的优化，如以已知三维结构同源序列为基础进行结构预测。", "局部比对仅获得特定序列在数据库中配对最好的亚区，考虑序列片段之间的相似性。"], "check": {"q": "关于双序列比对中的全局比对和局部比对，下列说法正确的是？", "o": ["A. 全局比对只比较序列中配对最好的亚区", "B. 局部比对对给定序列全长进行比较", "C. 全局比对考虑序列全局相似性，适用于高度同源序列的优化", "D. 局部比对必须引入空位使两条序列全长都得到比较"], "a": "C", "e": "全局比对考虑序列的全局相似性，对给定序列全长进行比较，适用于高度同源序列的优化；局部比对仅获得特定序列在数据库中配对最好的亚区。"}, "cards": [{"front": "什么是序列比对？其生物学意义是什么？", "back": "序列比对是运用特定数学模型或算法，找出两个或多个序列之间的最大匹配碱基或残基数，反映序列间相似性关系及生物学特征。它是序列分析和数据库搜索的基础，可用于寻找保守基序、判定同源性、预测新基因功能。", "mnemonic": "比对找相似，保守同源功能", "useImg": false}, {"front": "双序列比对与多序列比对的主要区别是什么？", "back": "双序列比对比较两条序列的相似区域和保守位点，寻找分子进化关系；多序列比对寻找共同保守区域、位点和模式，探索共同功能。", "mnemonic": "双比找进化，多比找保守", "useImg": false}, {"front": "全局比对和局部比对有何不同？", "back": "全局比对考虑序列的全局相似性，对给定序列全长进行比较，引入空位使全长都得到比较，适用于高度同源序列的优化；局部比对仅获得特定序列在数据库中配对最好的亚区，考虑序列片段之间的相似性。", "mnemonic": "全局全长，局部亚区", "useImg": false}]}, {"i": 2, "sec": "第一节 序列比对相关概念", "title": "编辑操作与编辑距离", "notes": "引入字符编辑操作（edit operation）解决字符插入和删除问题，通过编辑操作将一个序列转化为另一个序列。用字符“-”代表空位（gap）。定义：Match(a,a)字符匹配；Delete(a,-)从第一条序列删除字符a或在第二条序列相应位置插入空位；Replace(a,b)以第二条序列字符b替换第一条序列字符a；Insert(-,b)在第一条序列插入空位或删除第二条序列对应字符b。在一条序列中的删除操作等价于另一条序列对应位置上的插入操作。两个空位字符不能匹配。通过编辑操作计算的两条序列距离称为编辑距离（edit distance）。", "page": 41, "level": "掌握", "img": "assets/img/ch03/p041.jpg", "anim": null, "fig": null, "points": ["全局序列比对对给定序列全长进行比较，在待比较两序列中引入空位，使序列全长都得到比较，得到分数最高的比对。", "给定序列A=a1…am和B=b1…bn，S(i,j)表示两个序列所有比对的最好分数。", "递归关系：S(i,j)=max{S(i-1,j-1)+p(ai,bj), S(i-1,j)+p(ai,-), S(i,j-1)+p(-,bj)}。", "全局比对主要优势在于对具有高度同源性的序列进行优化。"], "check": {"q": "在编辑操作与编辑距离中，用字符“-”代表空位，下列对应关系正确的是？", "o": ["A. Match(a,a)表示字符a被b替换", "B. Delete(a,-)表示从第一条序列删除字符a或在第二条序列相应位置插入空位", "C. Replace(a,b)表示在第一条序列插入空位", "D. Insert(-,b)表示从第一条序列删除字符b"], "a": "B", "e": "Delete(a,-)表示从第一条序列删除字符a或在第二条序列相应位置插入空位；Replace(a,b)表示以第二条序列字符b替换第一条序列字符a；Insert(-,b)表示在第一条序列插入空位或删除第二条序列对应字符b。"}, "cards": [{"front": "序列比对中的编辑操作有哪些？", "back": "Match(a,a)字符匹配；Delete(a,-)从第一条序列删除字符a或在第二条序列相应位置插入空位；Replace(a,b)以第二条序列字符b替换第一条序列字符a；Insert(-,b)在第一条序列插入空位或删除第二条序列对应字符b。", "mnemonic": "匹配、删除、替换、插入", "useImg": false}, {"front": "打分函数与代价函数在序列比对中如何定义？", "back": "代价函数w表示代价，如w(a,a)=0 Match，w(a,b)=1 Replace，w(a,-)=w(-,b)=1 Delete/Insert；得分函数p表示得分，如p(a,a)=1 Match，p(a,b)=0 Replace，p(a,-)=p(-,b)=-1。比对得分（或代价）等于将一条序列转化为另一条序列所用所有编辑操作的得分（或代价）之和。", "mnemonic": "代价正，得分负，总和定优劣", "useImg": false}, {"front": "全局比对动态规划的递归关系是什么？", "back": "给定序列A=a1…am和B=b1…bn，S(i,j)表示两个序列所有比对的最好分数。递归关系：S(i,j)=max{S(i-1,j-1)+p(ai,bj), S(i-1,j)+p(ai,-), S(i,j-1)+p(-,bj)}。", "mnemonic": "对角、上、左取最大", "useImg": false}]}, {"i": 3, "sec": "第一节 序列比对相关概念", "title": "打分函数与最优比对", "notes": "就不同类型编辑操作定义代价函数w表示代价（cost），如w(a,a)=0 Match，w(a,b)=1 Replace，w(a,-)=w(-,b)=1 Delete/Insert。也可使用得分函数p表示得分（score），如p(a,a)=1 Match，p(a,b)=0 Replace，p(a,-)=p(-,b)=-1。两条序列的比对得分（或代价）等于将一条序列转化为另一条序列所用所有编辑操作的得分（或代价）总和。最优比对是所有可能比对中得分最高（或代价最小）的比对。最小编辑距离应在得分函数赋值（或代价函数赋值）下计算。序列比对目的是寻找得分最高（或代价最小）的比对。", "page": 41, "level": "掌握", "img": "assets/img/ch03/p041.jpg", "anim": null, "fig": null, "points": ["全局序列比对对给定序列全长进行比较，在待比较两序列中引入空位，使序列全长都得到比较，得到分数最高的比对。", "给定序列A=a1…am和B=b1…bn，S(i,j)表示两个序列所有比对的最好分数。", "递归关系：S(i,j)=max{S(i-1,j-1)+p(ai,bj), S(i-1,j)+p(ai,-), S(i,j-1)+p(-,bj)}。", "全局比对主要优势在于对具有高度同源性的序列进行优化。"], "check": {"q": "关于打分函数与最优比对，下列说法正确的是？", "o": ["A. 比对得分等于所有编辑操作得分的最大值，而不是总和", "B. 最优比对是所有可能比对中得分最低或代价最高的比对", "C. 两条序列的比对得分等于将一条序列转化为另一条序列所用所有编辑操作的得分总和", "D. 使用得分函数时，Match通常赋值为0，Replace赋值为1"], "a": "C", "e": "两条序列的比对得分或代价等于将一条序列转化为另一条序列所用所有编辑操作的得分或代价总和；最优比对是所有可能比对中得分最高或代价最低的比对。"}, "cards": [{"front": "序列比对中的编辑操作有哪些？", "back": "Match(a,a)字符匹配；Delete(a,-)从第一条序列删除字符a或在第二条序列相应位置插入空位；Replace(a,b)以第二条序列字符b替换第一条序列字符a；Insert(-,b)在第一条序列插入空位或删除第二条序列对应字符b。", "mnemonic": "匹配、删除、替换、插入", "useImg": false}, {"front": "打分函数与代价函数在序列比对中如何定义？", "back": "代价函数w表示代价，如w(a,a)=0 Match，w(a,b)=1 Replace，w(a,-)=w(-,b)=1 Delete/Insert；得分函数p表示得分，如p(a,a)=1 Match，p(a,b)=0 Replace，p(a,-)=p(-,b)=-1。比对得分（或代价）等于将一条序列转化为另一条序列所用所有编辑操作的得分（或代价）之和。", "mnemonic": "代价正，得分负，总和定优劣", "useImg": false}, {"front": "全局比对动态规划的递归关系是什么？", "back": "给定序列A=a1…am和B=b1…bn，S(i,j)表示两个序列所有比对的最好分数。递归关系：S(i,j)=max{S(i-1,j-1)+p(ai,bj), S(i-1,j)+p(ai,-), S(i,j-1)+p(-,bj)}。", "mnemonic": "对角、上、左取最大", "useImg": false}]}, {"i": 4, "sec": "第一节 序列比对相关概念", "title": "全局比对动态规划递归关系", "notes": "全局序列比对是对给定序列全长进行比较，在待比较两序列中引入空位，使序列全长都得到比较，得到分数最高的比对。给定序列A=a1…am和B=b1…bn，S(i,j)表示两个序列所有比对的最好分数。设定初值后可用递归关系计算：S(i,j)=max{S(i-1,j-1)+p(ai,bj), S(i-1,j)+p(ai,-), S(i,j-1)+p(-,bj)}。全局比对主要优势在于对具有高度同源性的序列进行优化，在以已知三维结构的同源序列为基础对未知序列三维结构进行预测的模型构建过程中十分有用。", "page": 41, "level": "掌握", "img": "assets/img/ch03/p041.jpg", "anim": null, "fig": null, "points": ["全局序列比对对给定序列全长进行比较，在待比较两序列中引入空位，使序列全长都得到比较，得到分数最高的比对。", "给定序列A=a1…am和B=b1…bn，S(i,j)表示两个序列所有比对的最好分数。", "递归关系：S(i,j)=max{S(i-1,j-1)+p(ai,bj), S(i-1,j)+p(ai,-), S(i,j-1)+p(-,bj)}。", "全局比对主要优势在于对具有高度同源性的序列进行优化。"], "check": {"q": "在全局比对动态规划递归关系中，S(i,j)通常表示？", "o": ["A. 序列A前i个字符与序列B前j个字符所有比对的最好分数", "B. 序列A第i个字符与序列B第j个字符是否相同的布尔值", "C. 序列A和B之间空位总数", "D. 序列A和B的长度差"], "a": "A", "e": "给定序列A=a1…am和B=b1…bn，S(i,j)表示两个序列所有比对的最好分数，递归关系为S(i,j)=max{S(i-1,j-1)+p(ai,bj), S(i-1,j)+p(ai,-), S(i,j-1)+p(-,bj)}。"}, "cards": [{"front": "序列比对中的编辑操作有哪些？", "back": "Match(a,a)字符匹配；Delete(a,-)从第一条序列删除字符a或在第二条序列相应位置插入空位；Replace(a,b)以第二条序列字符b替换第一条序列字符a；Insert(-,b)在第一条序列插入空位或删除第二条序列对应字符b。", "mnemonic": "匹配、删除、替换、插入", "useImg": false}, {"front": "打分函数与代价函数在序列比对中如何定义？", "back": "代价函数w表示代价，如w(a,a)=0 Match，w(a,b)=1 Replace，w(a,-)=w(-,b)=1 Delete/Insert；得分函数p表示得分，如p(a,a)=1 Match，p(a,b)=0 Replace，p(a,-)=p(-,b)=-1。比对得分（或代价）等于将一条序列转化为另一条序列所用所有编辑操作的得分（或代价）之和。", "mnemonic": "代价正，得分负，总和定优劣", "useImg": false}, {"front": "全局比对动态规划的递归关系是什么？", "back": "给定序列A=a1…am和B=b1…bn，S(i,j)表示两个序列所有比对的最好分数。递归关系：S(i,j)=max{S(i-1,j-1)+p(ai,bj), S(i-1,j)+p(ai,-), S(i,j-1)+p(-,bj)}。", "mnemonic": "对角、上、左取最大", "useImg": false}]}, {"i": 5, "sec": "第二节 序列比对打分方法", "title": "相似性与同源性、直系同源与旁系同源", "notes": "相似性高并不等于同源性，但大多数情况下相似性可表明同源性。发现两个基因或蛋白质具有很高序列相似性时，推测它们具有共同进化历程，判断具有相似生物学功能，但推断成为结论前必须经过实验验证。来自共同祖先的基因称为同源基因（homolog）。直系同源基因（orthologous gene）指不同物种中有相同功能的同源基因，在物种形成过程中形成；旁系同源基因（paralogous gene）指一个物种内的同源基因，是种内基因倍增的结果。直系同源由共同祖先演化而来，具有序列相似性；旁系同源一般有相似但并不相同的功能。实践中区分二者单从序列信息出发并不容易。", "page": 43, "level": "掌握", "img": "assets/img/ch03/p043.jpg", "anim": null, "fig": null, "points": ["相似性高并不等于同源性，但大多数情况下相似性可表明同源性。", "发现两个基因或蛋白质具有很高序列相似性时，推测它们具有共同进化历程，判断具有相似生物学功能，但推断成为结论前必须经过实验验证。", "来自共同祖先的基因称为同源基因。", "直系同源基因指不同物种中有相同功能的同源基因，在物种形成过程中形成；旁系同源基因指一个物种内的同源基因，由基因复制产生。"], "check": {"q": "关于相似性与同源性、直系同源与旁系同源，下列说法正确的是？", "o": ["A. 相似性高一定等于同源性，无需实验验证", "B. 直系同源基因是一个物种内基因倍增的结果", "C. 旁系同源基因是不同物种中在物种形成过程中形成的同源基因", "D. 直系同源基因指不同物种中有相同功能的同源基因，在物种形成过程中形成"], "a": "D", "e": "直系同源基因指不同物种中有相同功能的同源基因，在物种形成过程中形成；旁系同源基因指一个物种内的同源基因，是种内基因倍增的结果。相似性高并不等于同源性。"}, "cards": [{"front": "相似性与同源性有何关系？直系同源与旁系同源如何区分？", "back": "相似性高并不等于同源性，但大多数情况下相似性可表明同源性。发现两个基因或蛋白质具有很高序列相似性时，推测它们具有共同进化历程，判断具有相似生物学功能，但推断成为结论前必须经过实验验证。来自共同祖先的基因称为同源基因。直系同源基因指不同物种中有相同功能的同源基因，在物种形成过程中形成；旁系同源基因指一个物种内的同源基因，由基因复制产生。", "mnemonic": "相似非同源，直系种间，旁系种内", "useImg": false}]}, {"i": 6, "sec": "第二节 序列比对打分方法", "title": "打分矩阵的概念与稀疏矩阵", "notes": "序列分析目的是揭示核苷酸或氨基酸序列编码的高级结构或功能信息。简单相似性评价模型没有考虑同类字符与非同类字符替换的差别。不同类型字符替换代价和得分差别很大，尤其对蛋白质序列。保守替换比随机替换更可能维持蛋白质功能，理化性质相近的氨基酸残基之间替换应比相距甚远的替换得分高。打分矩阵（scoring matrix）是序列比较的基础，选择不同打分矩阵将得到不同比较结果。只考虑残基同一性的矩阵可理解为打分值为1和0的矩阵，相同残基打1分、不同残基打0分，通常称为稀疏（sparse）矩阵，大多数矩阵单元值为0，具有很大局限性。", "page": 44, "level": "掌握", "img": "assets/img/ch03/p044.jpg", "anim": null, "fig": null, "points": ["两个核酸序列比对较为简单。", "序列中嘌呤被嘧啶替换或反之称为颠换，如A→C、G→T；同类核苷酸替换称为转换，如A→G、C→T。", "可对核苷酸的颠换与转换给予不同评分。", "不考虑字母替换时可用单位矩阵作打分矩阵或取代矩阵，即相同核苷酸计1分、否则计0分。", "也有用0.99和0.0033等概率值构成的核酸比对打分矩阵；如果考虑颠换和转换，可采用区分二者的打分矩阵。"], "check": {"q": "关于打分矩阵的概念与稀疏矩阵，下列说法正确的是？", "o": ["A. 简单相似性评价模型充分考虑了同类字符与非同类字符替换的差别", "B. 打分矩阵是序列比较的基础，选择不同打分矩阵将得到不同比较结果", "C. 保守替换通常比随机替换更不可能维持蛋白质功能", "D. 只考虑残基同一性的矩阵中，相同残基打0分、不同残基打1分"], "a": "B", "e": "打分矩阵是序列比较的基础，选择不同打分矩阵将得到不同比较结果；保守替换比随机替换更可能维持蛋白质功能，理化性质相近的氨基酸残基之间替换应比相距甚远的替换得分高。"}, "cards": [{"front": "为什么需要打分矩阵？", "back": "序列分析目的是揭示核苷酸或氨基酸序列编码的高级结构或功能信息。简单相似性评价模型没有考虑同类字符与非同类字符替换的差别。不同类型字符替换代价和得分差别很大，尤其对蛋白质序列。保守替换比随机替换更可能维持蛋白质功能，理化性质相近的氨基酸残基之间替换应比相距甚远的替换得分高。打分矩阵是序列比较的基础，选择不同打分矩阵将得到不同比较结果。", "mnemonic": "保守替换得分高，打分矩阵定基础", "useImg": false}, {"front": "DNA打分矩阵中转换与颠换有何区别？", "back": "序列中嘌呤被嘧啶替换或反之称为颠换，如A→C、G→T；同类核苷酸替换称为转换，如A→G、C→T。可对核苷酸的颠换与转换给予不同评分。不考虑字母替换时可用单位矩阵作打分矩阵或取代矩阵，即相同核苷酸计1分、否则计0分。也有用0.99和0.0033等概率值构成的核酸比对打分矩阵；如果考虑颠换和转换，可采用区分二者的打分矩阵。", "mnemonic": "转换同类，颠换异类", "useImg": false}]}, {"i": 7, "sec": "第二节 序列比对打分方法", "title": "DNA打分矩阵与转换/颠换", "notes": "两个核酸序列比对较为简单。序列中嘌呤被嘧啶替换或反之称为颠换（transversion），如A→C、G→T；同类核苷酸替换称为转换（transition），如A→G、C→T。可对核苷酸的颠换与转换给予不同评分。不考虑字母替换时可用单位矩阵作打分矩阵或取代矩阵，即相同核苷酸计1分、否则计0分。也有用0.99和0.0033等概率值构成的核酸比对打分矩阵。如果考虑颠换和转换，可采用区分二者的打分矩阵，如A对G为0.006、A对C为0.002等，体现转换比颠换更常见。", "page": 44, "level": "理解", "img": "assets/img/ch03/p044.jpg", "anim": null, "fig": null, "points": ["两个核酸序列比对较为简单。", "序列中嘌呤被嘧啶替换或反之称为颠换，如A→C、G→T；同类核苷酸替换称为转换，如A→G、C→T。", "可对核苷酸的颠换与转换给予不同评分。", "不考虑字母替换时可用单位矩阵作打分矩阵或取代矩阵，即相同核苷酸计1分、否则计0分。", "也有用0.99和0.0033等概率值构成的核酸比对打分矩阵；如果考虑颠换和转换，可采用区分二者的打分矩阵。"], "check": {"q": "关于DNA打分矩阵与转换/颠换，下列说法正确的是？", "o": ["A. A→G属于颠换，A→C属于转换", "B. 嘌呤被嘧啶替换或反之称为转换", "C. 同类核苷酸替换称为转换，如A→G、C→T", "D. 不考虑字母替换时，相同核苷酸计0分、否则计1分"], "a": "C", "e": "序列中嘌呤被嘧啶替换或反之称为颠换，如A→C、G→T；同类核苷酸替换称为转换，如A→G、C→T。不考虑字母替换时可用单位矩阵，即相同核苷酸计1分、否则计0分。"}, "cards": [{"front": "为什么需要打分矩阵？", "back": "序列分析目的是揭示核苷酸或氨基酸序列编码的高级结构或功能信息。简单相似性评价模型没有考虑同类字符与非同类字符替换的差别。不同类型字符替换代价和得分差别很大，尤其对蛋白质序列。保守替换比随机替换更可能维持蛋白质功能，理化性质相近的氨基酸残基之间替换应比相距甚远的替换得分高。打分矩阵是序列比较的基础，选择不同打分矩阵将得到不同比较结果。", "mnemonic": "保守替换得分高，打分矩阵定基础", "useImg": false}, {"front": "DNA打分矩阵中转换与颠换有何区别？", "back": "序列中嘌呤被嘧啶替换或反之称为颠换，如A→C、G→T；同类核苷酸替换称为转换，如A→G、C→T。可对核苷酸的颠换与转换给予不同评分。不考虑字母替换时可用单位矩阵作打分矩阵或取代矩阵，即相同核苷酸计1分、否则计0分。也有用0.99和0.0033等概率值构成的核酸比对打分矩阵；如果考虑颠换和转换，可采用区分二者的打分矩阵。", "mnemonic": "转换同类，颠换异类", "useImg": false}]}, {"i": 8, "sec": "第二节 序列比对打分方法", "title": "氨基酸序列打分矩阵与PAM/BLOSUM", "notes": "20种氨基酸彼此之间的替换远比核苷酸复杂，不同氨基酸残基之间相似性差别很大，相互替换概率也各不相同。根据氨基酸R基团的极性、带电性和化学结构等性质可划分为不同相似组。Dayhoff提出将20种氨基酸分为6组的简单处理方案：第一组C，第二组S、T、P、A、G，第三组N、D、E、Q，第四组H、R、K，第五组M、I、L、V，第六组F、Y、W，同组残基等量齐观，把20种符号简化为6种。更常用方法是统计自然界中各种氨基酸残基的相互替换率，常用PAM矩阵（Dayhoff突变数据矩阵）和BLOSUM矩阵。", "page": 45, "level": "掌握", "img": "assets/img/ch03/p045.jpg", "anim": null, "fig": null, "points": ["20种氨基酸彼此之间的替换远比核苷酸复杂，不同氨基酸残基之间相似性差别很大，相互替换概率也各不相同。", "根据氨基酸R基团的极性、带电性和化学结构等性质可划分为不同相似组。", "Dayhoff提出将20种氨基酸分为6组的简单处理方案：第一组C，第二组S、T、P、A、G，第三组N、D、E、Q，第四组H、R、K，第五组M、I、L、V，第六组F、Y、W，同组残基等量齐观，把20种符号简化为6种。", "更常用方法是统计自然发生的氨基酸替换频率，构建PAM和BLOSUM等打分矩阵。"], "check": {"q": "关于氨基酸序列打分矩阵与PAM/BLOSUM，下列说法正确的是？", "o": ["A. Dayhoff将20种氨基酸分为6组，其中第一组为C", "B. Dayhoff将20种氨基酸分为20组，每组一种氨基酸", "C. PAM和BLOSUM矩阵只适用于核苷酸序列", "D. 同组残基在Dayhoff方案中不能等量齐观"], "a": "A", "e": "Dayhoff提出将20种氨基酸分为6组的简单处理方案：第一组C，第二组S、T、P、A、G，第三组N、D、E、Q，第四组H、R、K，第五组M、I、L、V，第六组F、Y、W。"}, "cards": [{"front": "氨基酸序列打分矩阵中PAM和BLOSUM有何区别？", "back": "20种氨基酸彼此之间的替换远比核苷酸复杂，不同氨基酸残基之间相似性差别很大，相互替换概率也各不相同。根据氨基酸R基团的极性、带电性和化学结构等性质可划分为不同相似组。Dayhoff提出将20种氨基酸分为6组的简单处理方案：第一组C，第二组S、T、P、A、G，第三组N、D、E、Q，第四组H、R、K，第五组M、I、L、V，第六组F、Y、W，同组残基等量齐观，把20种符号简化为6种。更常用方法是统计自然发生的氨基酸替换频率，构建PAM和BLOSUM等打分矩阵。", "mnemonic": "PAM基于进化模型，BLOSUM基于保守块", "useImg": false}]}, {"i": 9, "sec": "第三节 序列比对算法", "title": "dotplot算法", "notes": "dotplot算法是最古老的序列比对算法，通过点阵作图方法表示，能直观看出两条序列之间的相似性。构建点阵矩阵：在一个矩阵中，将两条序列的碱基（或残基）分别沿x轴和y轴排列，依次比较两条序列的每个碱基（或残基），如果两个碱基（或残基）相同则在矩阵交点中填充点，形成点阵矩阵。获得相似性片段：在点阵矩阵中，将位于对角线方向上相邻的点连接起来，这些直线所对应的矩形区域就是两条序列的相似性片段。算法特点：由于算法思想所限，dotplot算法获得的相似性片段实际上是相同片段，不能提供相似片段在统计学意义上的相似性。在线创建点阵矩阵工具有Dotlet。", "page": 49, "level": "理解", "img": "assets/img/ch03/p049.jpg", "anim": null, "fig": null, "points": ["dotplot算法是最古老的序列比对算法，通过点阵作图方法表示，能直观看出两条序列之间的相似性。", "构建点阵矩阵：在一个矩阵中，将两条序列的碱基（或残基）分别沿x轴和y轴排列，依次比较两条序列的每个碱基（或残基），如果两个碱基（或残基）相同则在矩阵交点中填充点，形成点阵矩阵。", "获得相似性片段：在点阵矩阵中，将位于对角线方向上相邻的点连接起来，这些直线所对应的矩形区域就是两条序列的相似性片段。", "算法特点：直观，但计算量大，适用于短序列或序列片段比较。"], "check": {"q": "关于dotplot算法，下列说法正确的是？", "o": ["A. dotplot算法是最新提出的高精度动态规划算法", "B. dotplot算法通过点阵作图方法表示两条序列之间的相似性", "C. 在dotplot矩阵中，如果两个碱基不同则在矩阵交点中填充点", "D. dotplot算法获得的相似性片段不能通过对角线方向相邻点连接获得"], "a": "B", "e": "dotplot算法是最古老的序列比对算法，通过点阵作图方法表示两条序列之间的相似性；相同则在矩阵交点中填充点，对角线方向上相邻的点连接起来可形成相似性片段。"}, "cards": [{"front": "dotplot算法如何构建和解读？", "back": "dotplot算法是最古老的序列比对算法，通过点阵作图方法表示，能直观看出两条序列之间的相似性。构建点阵矩阵：在一个矩阵中，将两条序列的碱基（或残基）分别沿x轴和y轴排列，依次比较两条序列的每个碱基（或残基），如果两个碱基（或残基）相同则在矩阵交点中填充点，形成点阵矩阵。获得相似性片段：在点阵矩阵中，将位于对角线方向上相邻的点连接起来，这些直线所对应的矩形区域就是两条序列的相似性片段。算法特点：直观，但计算量大，适用于短序列或序列片段比较。", "mnemonic": "点阵找对角线，相似片段现", "useImg": false}]}, {"i": 10, "sec": "第三节 序列比对算法", "title": "动态规划算法：Needleman-Wunsch与Smith-Waterman", "notes": "动态规划算法（dynamic programming algorithm）是最精确的序列比对算法，分为全局动态规划算法和局部动态规划算法。经典全局动态规划算法由Needleman和Wunsch于1970年提出，称为Needleman-Wunsch算法，用于发现两条序列全局水平上的相似性。经典局部动态规划算法由Smith和Waterman于1981年提出，称为Smith-Waterman算法，用于发现两条序列局部水平上的相似性。算法步骤：1.计算得分矩阵，使用迭代方法计算两个序列的相似分值，存于得分矩阵中，Needleman-Wunsch与Smith-Waterman计算方法相同；2.寻找最优比对序列，根据得分矩阵从最佳路径终点利用回溯法寻找最优路径。全局算法最佳路径终点在最后一行最后一列，局部算法最佳路径终点在元素值最大的位置。", "page": 50, "level": "掌握", "img": "assets/img/ch03/p050.jpg", "anim": null, "fig": null, "points": ["动态规划算法是最精确的序列比对算法，分为全局动态规划算法和局部动态规划算法。", "经典全局动态规划算法由Needleman和Wunsch于1970年提出，称为Needleman-Wunsch算法，用于发现两条序列全局水平上的相似性。", "经典局部动态规划算法由Smith和Waterman于1981年提出，称为Smith-Waterman算法，用于发现两条序列局部水平上的相似性。"], "check": {"q": "关于动态规划算法Needleman-Wunsch与Smith-Waterman，下列说法正确的是？", "o": ["A. Needleman-Wunsch算法用于发现两条序列局部水平上的相似性", "B. Smith-Waterman算法由Needleman和Wunsch于1970年提出", "C. Needleman-Wunsch算法是经典全局动态规划算法，用于发现全局水平上的相似性", "D. Smith-Waterman算法是全局动态规划算法，不能用于局部比对"], "a": "C", "e": "经典全局动态规划算法由Needleman和Wunsch于1970年提出，称为Needleman-Wunsch算法；经典局部动态规划算法由Smith和Waterman于1981年提出，称为Smith-Waterman算法。"}, "cards": [{"front": "Needleman-Wunsch和Smith-Waterman算法有何区别？", "back": "动态规划算法是最精确的序列比对算法，分为全局动态规划算法和局部动态规划算法。经典全局动态规划算法由Needleman和Wunsch于1970年提出，称为Needleman-Wunsch算法，用于发现两条序列全局水平上的相似性。经典局部动态规划算法由Smith和Waterman于1981年提出，称为Smith-Waterman算法，用于发现两条序列局部水平上的相似性。", "mnemonic": "NW全局，SW局部", "useImg": false}]}, {"i": 11, "sec": "第三节 序列比对算法", "title": "动态规划算法特点与BLAST算法", "notes": "动态规划算法优点是比对非常精确，缺点是运行时间长，不适合数据量庞大的序列数据库搜索。BLAST算法由Altschul等在1990年提出，采用短片段匹配算法和有效统计模型找出目的序列和数据库之间的最佳局部比对效果，基本思想是通过产生数量更少但质量更好的增强点来提高速度。算法步骤：1.编译一个由查询序列生成的长度固定的字段编译列表；2.在数据库中扫描获得与编译列表字段匹配的序列记录；3.以编译列表中的字段对为中心向两端延伸以寻找超过阈值分数S的高分值片段对（HSP）。E值表示数据库搜索中随机条件下期望发生的得分大于S的不同比对数目，对假阳性结果进行估计。BLAST是近似算法，速度快且比较精确。动态规划适用于较少量序列之间比对，BLAST适用于从大量序列中搜索相似序列。", "page": 52, "level": "掌握", "img": "assets/img/ch03/p052.jpg", "anim": null, "fig": null, "points": ["FASTA是FAST-ALL的缩写，与序列储存格式FASTA无关，是一种可用于核酸和蛋白质序列的快速序列比对数据库搜索工具。", "该工具算法由Pearson与Lipman在1988年设计，程序版本不断更新升级，可下载使用或在线比对。", "英国EBI的FASTA工具被广泛使用。", "FASTA工具是一个程序集合，主要包括FASTA、FASTX/Y、FASTF、FASTS和TFASTX/Y。"], "check": {"q": "关于动态规划算法特点与BLAST算法，下列说法正确的是？", "o": ["A. 动态规划算法运行时间短，适合大规模数据库搜索", "B. BLAST算法由Smith和Waterman于1981年提出", "C. BLAST算法采用短片段匹配算法和有效统计模型，提高数据库搜索速度", "D. BLAST算法通过产生更多但质量更差的增强点来提高速度"], "a": "C", "e": "动态规划算法优点是比对非常精确，缺点是运行时间长，不适合数据量庞大的序列数据库搜索；BLAST算法由Altschul等在1990年提出，采用短片段匹配算法和有效统计模型，通过产生数量更少但质量更好的增强点来提高速度。"}, "cards": [{"front": "动态规划算法有何优缺点？BLAST算法的基本思想和步骤是什么？", "back": "动态规划算法优点是比对非常精确，缺点是运行时间长，不适合数据量庞大的序列数据库搜索。BLAST算法由Altschul等在1990年提出，采用短片段匹配算法和有效统计模型找出目的序列和数据库之间的最佳局部比对效果，基本思想是通过产生数量更少但质量更好的增强点来提高速度。算法步骤：1.编译一个由查询序列生成的长度固定的字段编译列表；2.在数据库中扫描获得与编译列表字段匹配的序列记录；3.以编译列表中的字段为种子，延伸匹配片段，获得高分片段对。", "mnemonic": "动态规划精确慢，BLAST种子延伸快", "useImg": false}, {"front": "FASTA工具是什么？有哪些主要程序？", "back": "FASTA是FAST-ALL的缩写，与序列储存格式FASTA无关，是一种可用于核酸和蛋白质序列的快速序列比对数据库搜索工具。该工具算法由Pearson与Lipman在1988年设计，程序版本不断更新升级，可下载使用或在线比对。英国EBI的FASTA工具被广泛使用。FASTA工具是一个程序集合，主要包括FASTA、FASTX/Y、FASTF、FASTS和TFASTX/Y。", "mnemonic": "FASTA快速搜，程序集合多", "useImg": false}]}, {"i": 12, "sec": "第四节 序列比对工具", "title": "FASTA工具", "notes": "FASTA是FAST-ALL的缩写，与序列储存格式FASTA无关，是一种可用于核酸和蛋白质序列的快速序列比对数据库搜索工具。该工具算法由Pearson与Lipman在1988年设计，程序版本不断更新升级，可下载使用或在线比对。英国EBI的FASTA工具被广泛使用。FASTA工具是一个程序集合，主要包括FASTA、FASTX/Y、FASTF、FASTS和TFASTX/Y。FASTA将DNA与DNA数据库或蛋白质与蛋白质数据库进行相似性搜索；FASTX/Y将DNA正向翻译成3种可能蛋白质序列后分别与蛋白质数据库搜索；FASTF将混合无序多肽片段与蛋白质数据库搜索；FASTS将有序多肽片段与蛋白质数据库搜索；TFASTX/Y将DNA数据库每条序列翻译成6种可能蛋白质后与待搜索蛋白质序列搜索。随着序列数量快速增长，FASTA搜索速度逐渐被BLAST代替。", "page": 52, "level": "理解", "img": "assets/img/ch03/p052.jpg", "anim": null, "fig": null, "points": ["FASTA是FAST-ALL的缩写，与序列储存格式FASTA无关，是一种可用于核酸和蛋白质序列的快速序列比对数据库搜索工具。", "该工具算法由Pearson与Lipman在1988年设计，程序版本不断更新升级，可下载使用或在线比对。", "英国EBI的FASTA工具被广泛使用。", "FASTA工具是一个程序集合，主要包括FASTA、FASTX/Y、FASTF、FASTS和TFASTX/Y。"], "check": {"q": "关于FASTA工具，下列说法正确的是？", "o": ["A. FASTA是序列储存格式FASTA的缩写，与比对工具无关", "B. FASTA是FAST-ALL的缩写，可用于核酸和蛋白质序列的快速序列比对数据库搜索", "C. FASTA工具只能用于蛋白质与蛋白质数据库的相似性搜索", "D. FASTA工具由Altschul等在1990年设计"], "a": "B", "e": "FASTA是FAST-ALL的缩写，与序列储存格式FASTA无关，是一种可用于核酸和蛋白质序列的快速序列比对数据库搜索工具，由Pearson与Lipman在1988年设计。"}, "cards": [{"front": "动态规划算法有何优缺点？BLAST算法的基本思想和步骤是什么？", "back": "动态规划算法优点是比对非常精确，缺点是运行时间长，不适合数据量庞大的序列数据库搜索。BLAST算法由Altschul等在1990年提出，采用短片段匹配算法和有效统计模型找出目的序列和数据库之间的最佳局部比对效果，基本思想是通过产生数量更少但质量更好的增强点来提高速度。算法步骤：1.编译一个由查询序列生成的长度固定的字段编译列表；2.在数据库中扫描获得与编译列表字段匹配的序列记录；3.以编译列表中的字段为种子，延伸匹配片段，获得高分片段对。", "mnemonic": "动态规划精确慢，BLAST种子延伸快", "useImg": false}, {"front": "FASTA工具是什么？有哪些主要程序？", "back": "FASTA是FAST-ALL的缩写，与序列储存格式FASTA无关，是一种可用于核酸和蛋白质序列的快速序列比对数据库搜索工具。该工具算法由Pearson与Lipman在1988年设计，程序版本不断更新升级，可下载使用或在线比对。英国EBI的FASTA工具被广泛使用。FASTA工具是一个程序集合，主要包括FASTA、FASTX/Y、FASTF、FASTS和TFASTX/Y。", "mnemonic": "FASTA快速搜，程序集合多", "useImg": false}]}, {"i": 13, "sec": "第四节 序列比对工具", "title": "BLAST工具：基本程序与参数", "notes": "BLAST工具是有效的序列数据库搜索工具，通过BLAST算法从核酸或蛋白质序列数据库中找出与待检序列具有一定程度相似性的序列。BLAST工具是程序集合，包括基本BLAST工具和高级BLAST工具。基本BLAST工具包括blastn、blastp、blastx、tblastn和tblastx。blastn将DNA查询序列不同方向两条链与DNA数据库比较；blastp将蛋白质查询序列与蛋白质数据库比较；blastx将DNA序列用所有可能阅读框翻译成6个蛋白质后逐一与蛋白质数据库比较；tblastn将DNA数据库中每条序列翻译成6种可能蛋白质后与查询蛋白质序列比较；tblastx将查询DNA及数据库DNA都翻译成6种可能蛋白质后进行36次蛋白质-蛋白质数据库搜索。参数包括Database（nr、refseq_protein、swissprot、pdb等）、Organism、Entrez Query、Expect threshold（默认10）、Word size（默认3）、Matrix（默认BLOSUM62）、Gap costs（开放罚分默认11，延伸罚分默认1）。", "page": 53, "level": "掌握", "img": "assets/img/ch03/p053.jpg", "anim": null, "fig": null, "points": ["BLAST工具是有效的序列数据库搜索工具，通过BLAST算法从核酸或蛋白质序列数据库中找出与待检序列具有一定程度相似性的序列。", "BLAST工具是程序集合，包括基本BLAST工具和高级BLAST工具。", "基本BLAST工具包括blastn、blastp、blastx、tblastn和tblastx。", "blastn将DNA查询序列不同方向两条链与DNA数据库比较；blastp将蛋白质查询序列与蛋白质数据库比较。"], "check": {"q": "关于BLAST工具的基本程序，下列说法正确的是？", "o": ["A. blastn将蛋白质查询序列与蛋白质数据库比较", "B. blastp将DNA查询序列与DNA数据库比较", "C. blastx将DNA序列用所有可能阅读框翻译后与蛋白质数据库比较", "D. tblastn将蛋白质查询序列与蛋白质数据库比较"], "a": "C", "e": "blastn将DNA查询序列不同方向两条链与DNA数据库比较；blastp将蛋白质查询序列与蛋白质数据库比较；blastx将DNA序列用所有可能阅读框翻译后与蛋白质数据库比较；tblastn将蛋白质查询序列与翻译后的DNA数据库比较。"}, "cards": [{"front": "BLAST工具的基本程序有哪些？各自功能是什么？", "back": "BLAST工具是有效的序列数据库搜索工具，通过BLAST算法从核酸或蛋白质序列数据库中找出与待检序列具有一定程度相似性的序列。BLAST工具是程序集合，包括基本BLAST工具和高级BLAST工具。基本BLAST工具包括blastn、blastp、blastx、tblastn和tblastx。blastn将DNA查询序列不同方向两条链与DNA数据库比较；blastp将蛋白质查询序列与蛋白质数据库比较。", "mnemonic": "blastn核酸，blastp蛋白，blastx翻译", "useImg": false}]}, {"i": 14, "sec": "第五节 多序列比对", "title": "多序列比对概述与定义", "notes": "多序列比对就是对3条以上（包括3条）序列进行的比对。目的通常是为了发现构成同一基因家族的成组序列之间的共性，对研究分子结构功能及进化关系有重要作用，在阐明一组相关序列的重要生物学模式方面也起重要作用。通过多序列比对可发现与结构域或功能相关的保守序列片段，发现蛋白质序列之间的系统发育关系，更好理解蛋白质之间进化关系。定义：对多条序列插入空位，使得插入空位后的全局比对结果具有相同长度，并且比对结果中不能出现一列全为空位。多序列比对是分子生物学中重要分析方法，可应用于发现新序列与已知序列家族的同源性、蛋白质序列二级和三级结构预测、发现蛋白之间系统发生关系、获取蛋白质家族中结构或功能相似片段等。", "page": 55, "level": "掌握", "img": "assets/img/ch03/p055.jpg", "anim": null, "fig": null, "points": ["多序列比对就是对3条以上（包括3条）序列进行的比对。", "目的通常是为了发现构成同一基因家族的成组序列之间的共性，对研究分子结构功能及进化关系有重要作用，在阐明一组相关序列的重要生物学模式方面也起重要作用。", "通过多序列比对可发现与结构域或功能相关的保守序列片段，发现蛋白质序列之间的系统发育关系，更好理解蛋白质之间进化关系。", "定义：对多条序列插入空位，使得插入空位后的全局比对结果具有相同长度，并且比对结果中不同序列的同一列具有同源性。"], "check": {"q": "关于多序列比对概述与定义，下列说法正确的是？", "o": ["A. 多序列比对是对2条以上序列进行的比对", "B. 多序列比对结果中允许出现一列全为空位", "C. 多序列比对是对3条以上（包括3条）序列进行的比对，插入空位后全局比对结果应具有相同长度", "D. 多序列比对不能用于发现保守序列片段"], "a": "C", "e": "多序列比对就是对3条以上（包括3条）序列进行的比对；定义要求对多条序列插入空位，使插入空位后的全局比对结果具有相同长度，并且比对结果中不能出现一列全为空位。"}, "cards": [{"front": "什么是多序列比对？其目的和定义是什么？", "back": "多序列比对就是对3条以上（包括3条）序列进行的比对。目的通常是为了发现构成同一基因家族的成组序列之间的共性，对研究分子结构功能及进化关系有重要作用，在阐明一组相关序列的重要生物学模式方面也起重要作用。通过多序列比对可发现与结构域或功能相关的保守序列片段，发现蛋白质序列之间的系统发育关系，更好理解蛋白质之间进化关系。定义：对多条序列插入空位，使得插入空位后的全局比对结果具有相同长度，并且比对结果中不同序列的同一列具有同源性。", "mnemonic": "三条以上，等长同源列", "useImg": false}]}, {"i": 15, "sec": "第五节 多序列比对", "title": "多序列比对算法：动态规划、渐进式、迭代与统计概率", "notes": "多序列比对动态规划算法与双序列比对思想相同，只是将维数由二维改为多维，打分矩阵为多维矩阵，分为打分矩阵计算和回溯寻找路径两步。渐进式算法是大多数多序列比对工具采用的算法，基本思想基于相似序列通常具有进化相关性假设：首先进行双序列比对构建距离矩阵；然后进行指导树构建（guide tree，GT），根据距离矩阵计算产生指导树；最后进行渐进式比对，对关系密切的序列加权，从最紧密两条序列开始逐步引入邻近序列并不断重新构建比对，直到所有序列加入。迭代算法核心是使用比对记分函数反复添加附加序列到已知比对中。统计概率算法常用隐马尔可夫模型（HMM），描述大量相互联系状态之间发生转换概率的模型，本质上是一条表示匹配、缺失或插入状态的链，用于检测序列比对结果中的保守区。", "page": 56, "level": "掌握", "img": "assets/img/ch03/p056.jpg", "anim": null, "fig": null, "points": ["多序列比对动态规划算法与双序列比对思想相同，只是将维数由二维改为多维，打分矩阵为多维矩阵，分为打分矩阵计算和回溯寻找路径两步。", "渐进式算法是大多数多序列比对工具采用的算法，基本思想基于相似序列通常具有进化相关性假设。", "渐进式算法步骤：首先进行双序列比对构建距离矩阵；然后进行指导树构建，根据距离矩阵计算产生指导树；最后进行渐进式比对，对关系密切的序列加权，从最紧密两条序列开始逐步引入邻近序列。", "迭代算法和统计概率算法也是多序列比对中常用的方法。"], "check": {"q": "关于多序列比对算法，下列说法正确的是？", "o": ["A. 多序列比对动态规划算法将维数由二维改为多维，打分矩阵为多维矩阵", "B. 渐进式算法首先进行指导树构建，然后进行双序列比对构建距离矩阵", "C. 渐进式算法假设相似序列通常不具有进化相关性", "D. 渐进式比对通常从关系最远的序列开始逐步引入邻近序列"], "a": "A", "e": "多序列比对动态规划算法与双序列比对思想相同，只是将维数由二维改为多维，打分矩阵为多维矩阵；渐进式算法先进行双序列比对构建距离矩阵，再构建指导树，最后按指导树分支顺序从最紧密两条序列开始逐步引入邻近序列。"}, "cards": [{"front": "多序列比对的主要算法有哪些？渐进式算法的步骤是什么？", "back": "多序列比对动态规划算法与双序列比对思想相同，只是将维数由二维改为多维，打分矩阵为多维矩阵，分为打分矩阵计算和回溯寻找路径两步。渐进式算法是大多数多序列比对工具采用的算法，基本思想基于相似序列通常具有进化相关性假设。渐进式算法步骤：首先进行双序列比对构建距离矩阵；然后进行指导树构建，根据距离矩阵计算产生指导树；最后进行渐进式比对，对关系密切的序列加权，从最紧密两条序列开始逐步引入邻近序列。迭代算法和统计概率算法也是多序列比对中常用的方法。", "mnemonic": "动态规划多维，渐进式建树比对", "useImg": false}]}, {"i": 16, "sec": "第五节 多序列比对", "title": "多序列比对工具：Clustal系列", "notes": "Clustal是广泛使用的多序列比对工具，有ClustalX/W等版本。ClustalX是图形界面版本，ClustalW是命令行版本。Clustal采用渐进式算法，首先进行所有序列的两两比对构建距离矩阵，然后根据距离矩阵构建指导树，最后按照指导树的分支顺序进行渐进式比对。Clustal工具可对核酸和蛋白质序列进行多序列比对，输出结果可用于系统发育分析、保守区域识别等。使用时可设置空位开放罚分、空位延伸罚分、打分矩阵等参数。多序列比对结果可用于发现保守基序、预测蛋白质二级结构、构建系统发育树等。", "page": 57, "level": "理解", "img": "assets/img/ch03/p057.jpg", "anim": null, "fig": null, "points": ["Clustal是广泛使用的多序列比对工具，有ClustalX/W等版本。", "ClustalX是图形界面版本，ClustalW是命令行版本。", "Clustal采用渐进式算法，首先进行所有序列的两两比对构建距离矩阵，然后根据距离矩阵构建指导树，最后按照指导树的分支顺序进行渐进式比对。", "Clustal工具可对核酸和蛋白质序列进行多序列比对，输出结果可用于系统发育分析、保守区域识别等。", "使用时可设置空位开放罚分、空位延伸罚分等参数。"], "check": {"q": "关于多序列比对工具Clustal系列，下列说法正确的是？", "o": ["A. ClustalX是命令行版本，ClustalW是图形界面版本", "B. Clustal采用动态规划算法进行多序列比对", "C. Clustal采用渐进式算法，先构建距离矩阵，再构建指导树，最后按指导树分支顺序比对", "D. Clustal只能对蛋白质序列进行多序列比对"], "a": "C", "e": "Clustal是广泛使用的多序列比对工具，有ClustalX/W等版本；ClustalX是图形界面版本，ClustalW是命令行版本；Clustal采用渐进式算法，先进行所有序列的两两比对构建距离矩阵，然后根据距离矩阵构建指导树，最后按照指导树的分支顺序进行渐进式比对。"}, "cards": [{"front": "Clustal系列工具的特点是什么？", "back": "Clustal是广泛使用的多序列比对工具，有ClustalX/W等版本。ClustalX是图形界面版本，ClustalW是命令行版本。Clustal采用渐进式算法，首先进行所有序列的两两比对构建距离矩阵，然后根据距离矩阵构建指导树，最后按照指导树的分支顺序进行渐进式比对。Clustal工具可对核酸和蛋白质序列进行多序列比对，输出结果可用于系统发育分析、保守区域识别等。使用时可设置空位开放罚分、空位延伸罚分等参数。", "mnemonic": "Clustal渐进式，X图形W命令行", "useImg": false}]}], "mcq": [{"id": "ch03_mcq_1", "mod": "第三章 序列比对原理", "modI": 0, "q": "关于序列比对中全局比对与局部比对的描述，正确的是：", "o": ["A. 全局比对仅比较序列片段之间的相似性，局部比对比较序列全长", "B. 全局比对考虑序列的全局相似性，局部比对考虑序列片段之间的相似性", "C. 全局比对和局部比对都只考虑序列的局部相似性", "D. 全局比对适用于寻找保守基序，局部比对适用于高度同源序列优化"], "a": "B", "e": "全局比对（global alignment）考虑序列的全局相似性，对给定序列全长进行比较；局部比对（local alignment）考虑序列片段之间的相似性，仅获得特定序列在数据库中配对最好的亚区。A项颠倒，C项错误，D项中全局比对适用于高度同源序列优化，局部比对适用于寻找保守片段。", "kp": "ch03_s0_1"}, {"id": "ch03_mcq_2", "mod": "第三章 序列比对原理", "modI": 0, "q": "在序列比对中，字符编辑操作Replace(a,b)的含义是：", "o": ["A. 从第一条序列删除一个字符a", "B. 在第一条序列插入空位字符", "C. 以第二条序列中的字符b替换第一条序列中的字符a", "D. 字符a与字符b匹配"], "a": "C", "e": "Replace(a,b)表示以第二条序列中的字符b替换第一条序列中的字符a。Delete(a,-)表示从第一条序列删除一个字符a或在第二条序列相应位置插入空位；Insert(-,b)表示在第一条序列插入空位字符或删除第二条序列中对应字符b；Match(a,a)表示字符匹配。", "kp": "ch03_s0_2"}, {"id": "ch03_mcq_3", "mod": "第三章 序列比对原理", "modI": 0, "q": "关于直系同源基因和旁系同源基因，下列说法正确的是：", "o": ["A. 直系同源基因是一个物种内的同源基因，旁系同源基因是不同物种中的同源基因", "B. 直系同源基因是在物种形成过程中形成的，旁系同源基因是种内基因倍增的结果", "C. 直系同源基因和旁系同源基因都一定具有相同的生物学功能", "D. 直系同源基因由基因倍增产生，旁系同源基因由物种形成产生"], "a": "B", "e": "直系同源基因（orthologous gene）指不同物种中有相同功能的同源基因，在物种形成过程中形成；旁系同源基因（paralogous gene）指一个物种内的同源基因，是种内基因倍增的结果。A项颠倒，C项旁系同源一般有相似但并不相同的功能，D项颠倒。", "kp": "ch03_s0_5"}, {"id": "ch03_mcq_4", "mod": "第三章 序列比对原理", "modI": 0, "q": "关于DNA序列比对中的转换和颠换，下列描述正确的是：", "o": ["A. 转换是指嘌呤被嘧啶替换，如A→C", "B. 颠换是指同类核苷酸替换，如A→G", "C. 转换是指同类核苷酸替换，如A→G；颠换是指嘌呤被嘧啶替换或反之，如A→C", "D. 转换和颠换在打分矩阵中总是给予相同评分"], "a": "C", "e": "转换（transition）指同类核苷酸替换，如A→G、C→T；颠换（transversion）指嘌呤被嘧啶替换或反之，如A→C、G→T。可对核苷酸的颠换与转换给予不同评分，因为转换比颠换更常见。", "kp": "ch03_s0_7"}, {"id": "ch03_mcq_5", "mod": "第三章 序列比对原理", "modI": 0, "q": "关于dotplot算法，下列说法错误的是：", "o": ["A. dotplot算法是最古老的序列比对算法，通过点阵作图方法表示", "B. 在点阵矩阵中，将位于对角线方向上相邻的点连接起来可获得相似性片段", "C. dotplot算法能提供相似片段在统计学意义上的相似性", "D. dotplot算法获得的相似性片段实际上是相同片段"], "a": "C", "e": "dotplot算法由于算法思想所限，获得的相似性片段实际上是相同片段，而且不能提供相似片段在统计学意义上的相似性。A、B、D描述正确。", "kp": "ch03_s0_9"}, {"id": "ch03_mcq_6", "mod": "第三章 序列比对原理", "modI": 0, "q": "关于动态规划算法，下列描述正确的是：", "o": ["A. Needleman-Wunsch算法用于局部比对，Smith-Waterman算法用于全局比对", "B. Needleman-Wunsch算法由Smith和Waterman于1981年提出", "C. 全局动态规划算法最佳路径终点在最后一行最后一列，局部动态规划算法最佳路径终点在元素值最大的位置", "D. 动态规划算法运行时间短，适合大规模数据库搜索"], "a": "C", "e": "Needleman-Wunsch算法由Needleman和Wunsch于1970年提出，用于全局比对；Smith-Waterman算法由Smith和Waterman于1981年提出，用于局部比对。全局动态规划算法最佳路径终点在最后一行最后一列，局部动态规划算法最佳路径终点在元素值最大的位置。动态规划算法优点是精确，缺点是运行时间长，不适合大规模数据库搜索。", "kp": "ch03_s0_10"}, {"id": "ch03_mcq_7", "mod": "第三章 序列比对原理", "modI": 0, "q": "关于BLAST算法，下列说法正确的是：", "o": ["A. BLAST算法是一种精确算法，运行时间比动态规划算法长", "B. BLAST算法由Altschul等在1990年提出，采用短片段匹配算法和统计模型", "C. BLAST算法中E值越小表示假阳性结果越多", "D. BLAST算法适用于较少量序列之间的精确比对"], "a": "B", "e": "BLAST算法由Altschul等在1990年提出，采用短片段匹配算法和有效统计模型找出最佳局部比对效果，基本思想是通过产生数量更少但质量更好的增强点来提高速度。BLAST是近似算法，速度快且比较精确，适用于从大量序列中搜索相似序列。E值表示随机条件下期望发生的得分大于S的不同比对数目，E值越小表示假阳性结果越少。", "kp": "ch03_s0_11"}, {"id": "ch03_mcq_8", "mod": "第三章 序列比对原理", "modI": 0, "q": "BLAST工具中，将DNA序列用所有可能阅读框翻译成6个蛋白质，然后逐一与蛋白质数据库进行比较的程序是：", "o": ["A. blastn", "B. blastp", "C. blastx", "D. tblastn"], "a": "C", "e": "blastx将DNA序列用所有可能的阅读框翻译成6个蛋白质，然后将它们逐一与蛋白质数据库进行比较。blastn将DNA查询序列与DNA数据库比较；blastp将蛋白质查询序列与蛋白质数据库比较；tblastn将DNA数据库中每条序列翻译成6种可能蛋白质后与查询蛋白质序列比较。", "kp": "ch03_s0_13"}, {"id": "ch03_mcq_9", "mod": "第三章 序列比对原理", "modI": 0, "q": "关于多序列比对，下列说法错误的是：", "o": ["A. 多序列比对是对3条以上（包括3条）序列进行的比对", "B. 多序列比对结果中不能出现一列全为空位", "C. 渐进式算法是大多数多序列比对工具采用的算法", "D. 多序列比对只能用于发现保守序列片段，不能用于系统发育分析"], "a": "D", "e": "多序列比对可应用于发现新序列与已知序列家族的同源性、蛋白质序列二级和三级结构预测、发现蛋白之间系统发生关系、获取蛋白质家族中结构或功能相似片段等。A、B、C描述正确。渐进式算法基本思想基于相似序列通常具有进化相关性假设，是大多数多序列比对工具采用的算法。", "kp": "ch03_s0_1"}, {"id": "ch03_mcq_10", "mod": "第三章 序列比对原理", "modI": 0, "q": "关于隐马尔可夫模型（HMM）在多序列比对中的应用，下列说法正确的是：", "o": ["A. HMM本质上是一条仅表示匹配状态的链", "B. HMM用于多序列比对时，每个保守残基用匹配状态描述，空位插入用插入状态描述，残基缺失用缺失状态描述", "C. HMM不能用于检测序列比对结果中的保守区", "D. HMM是一种双序列比对算法"], "a": "B", "e": "HMM是描述大量相互联系状态之间发生转换概率的模型，本质上是一条表示匹配、缺失或插入状态的链。用于多序列比对计算时，可用来检测序列比对结果中的保守区。每个保守残基可用匹配状态描述，空位插入用插入状态描述，残基缺失状态表示允许在本该匹配的位置发生缺失。HMM是统计概率算法，用于多序列比对。", "kp": "ch03_s0_15"}], "judge": [{"id": "ch03_judge_1", "modI": 0, "q": "相似性高一定等于同源性。", "a": "错", "e": "相似性高并不等于同源性，但大多数情况下相似性可表明同源性。发现两个基因或蛋白质具有很高序列相似性时，推测它们具有共同进化历程，但推断成为结论前必须经过实验验证。", "kp": "ch03_s0_5"}, {"id": "ch03_judge_2", "modI": 0, "q": "直系同源基因指不同物种中有相同功能的同源基因，在物种形成过程中形成。", "a": "对", "e": "直系同源基因（orthologous gene）指不同物种中有相同功能的同源基因，在物种形成过程中形成。旁系同源基因指一个物种内的同源基因，是种内基因倍增的结果。", "kp": "ch03_s0_5"}, {"id": "ch03_judge_3", "modI": 0, "q": "两个空位字符可以匹配。", "a": "错", "e": "两个空位字符不能匹配。", "kp": "ch03_s0_2"}, {"id": "ch03_judge_4", "modI": 0, "q": "全局比对最佳路径终点在得分矩阵最后一行最后一列。", "a": "对", "e": "全局算法最佳路径终点在最后一行最后一列，局部算法最佳路径终点在元素值最大的位置。", "kp": "ch03_s0_10"}, {"id": "ch03_judge_5", "modI": 0, "q": "BLAST算法是精确算法，运行时间短。", "a": "错", "e": "BLAST是近似算法，速度快且比较精确。动态规划算法是最精确的序列比对算法，但运行时间长。", "kp": "ch03_s0_11"}, {"id": "ch03_judge_6", "modI": 0, "q": "FASTA工具与序列储存格式FASTA是同一概念。", "a": "错", "e": "FASTA是FAST-ALL的缩写，与序列储存格式FASTA无关，是一种可用于核酸和蛋白质序列的快速序列比对数据库搜索工具。", "kp": "ch03_s0_12"}, {"id": "ch03_judge_7", "modI": 0, "q": "ClustalX是命令行版本，ClustalW是图形界面版本。", "a": "错", "e": "ClustalX是图形界面版本，ClustalW是命令行版本。", "kp": "ch03_s0_16"}, {"id": "ch03_judge_8", "modI": 0, "q": "多序列比对结果中不能出现一列全为空位。", "a": "对", "e": "多序列比对定义：对多条序列插入空位，使得插入空位后的全局比对结果具有相同长度，并且比对结果中不能出现一列全为空位。", "kp": "ch03_s0_14"}, {"id": "ch03_judge_9", "modI": 0, "q": "dotplot算法能提供相似片段在统计学意义上的相似性。", "a": "错", "e": "由于算法思想所限，dotplot算法获得的相似性片段实际上是相同片段，不能提供相似片段在统计学意义上的相似性。", "kp": "ch03_s0_9"}, {"id": "ch03_judge_10", "modI": 0, "q": "BLAST中，tblastx将查询DNA及数据库DNA都翻译成6种可能蛋白质后进行36次蛋白质-蛋白质数据库搜索。", "a": "对", "e": "tblastx将查询DNA及数据库DNA都翻译成6种可能蛋白质后进行36次蛋白质-蛋白质数据库搜索。", "kp": "ch03_s0_13"}], "fill": [{"id": "ch03_fill_1", "modI": 0, "q": "序列比对中，全局比对经典算法为________，局部比对经典算法为________。", "a": "Needleman-Wunsch,Smith-Waterman", "kp": "ch03_s0_1"}, {"id": "ch03_fill_2", "modI": 0, "q": "在编辑操作中，用字符“________”代表空位。", "a": "-", "kp": "ch03_s0_2"}, {"id": "ch03_fill_3", "modI": 0, "q": "蛋白质序列比对常用的打分矩阵包括________和________。", "a": "PAM,BLOSUM", "kp": "ch03_s0_16"}, {"id": "ch03_fill_4", "modI": 0, "q": "BLAST工具中，________将DNA查询序列不同方向两条链与DNA数据库比较。", "a": "blastn", "kp": "ch03_s0_13"}, {"id": "ch03_fill_5", "modI": 0, "q": "BLAST工具中，________将DNA序列用所有可能阅读框翻译成6个蛋白质后逐一与蛋白质数据库比较。", "a": "blastx", "kp": "ch03_s0_13"}, {"id": "ch03_fill_6", "modI": 0, "q": "多序列比对渐进式算法中，首先进行双序列比对构建________，然后构建________，最后进行渐进式比对。", "a": "距离矩阵,指导树", "kp": "ch03_s0_15"}, {"id": "ch03_fill_7", "modI": 0, "q": "Clustal工具采用________算法进行多序列比对。", "a": "渐进式", "kp": "ch03_s0_16"}, {"id": "ch03_fill_8", "modI": 0, "q": "BLAST中，E值表示数据库搜索中随机条件下期望发生的得分大于S的不同比对数目，用于估计________结果。", "a": "假阳性", "kp": "ch03_s0_11"}], "short": [{"id": "ch03_short_1", "modI": 0, "q": "简述序列比对的生物学意义。", "a": "序列比对是序列分析和数据库搜索的基础。可用于寻找保守基序、判定同源性、预测新基因功能。双序列比对比较两条序列的相似区域和保守位点，寻找分子进化关系；多序列比对寻找共同保守区域、位点和模式，探索共同功能的序列模式。还可将蛋白质序列与核酸序列比较以探索表达框架，或与三维结构蛋白质比较获得结构折叠信息。", "kp": "ch03_s0_0"}, {"id": "ch03_short_2", "modI": 0, "q": "简述全局比对与局部比对的区别。", "a": "全局比对考虑序列的全局相似性，对给定序列全长进行比较，引入空位使全长都得到比较，适用于高度同源序列的优化，如以已知三维结构同源序列为基础进行结构预测。局部比对仅获得特定序列在数据库中配对最好的亚区，考虑序列片段之间的相似性。全局比对经典算法为Needleman-Wunsch，局部比对经典算法为Smith-Waterman。", "kp": "ch03_s0_1"}, {"id": "ch03_short_3", "modI": 0, "q": "简述BLAST算法的基本步骤。", "a": "1. 编译一个由查询序列生成的长度固定的字段编译列表；2. 在数据库中扫描获得与编译列表字段匹配的序列记录；3. 以编译列表中的字段对为中心向两端延伸以寻找超过阈值分数S的高分值片段对（HSP）。BLAST是近似算法，速度快且比较精确。", "kp": "ch03_s0_11"}, {"id": "ch03_short_4", "modI": 0, "q": "简述多序列比对的定义与目的。", "a": "定义：对3条以上（包括3条）序列插入空位，使得插入空位后的全局比对结果具有相同长度，并且比对结果中不能出现一列全为空位。目的：发现构成同一基因家族的成组序列之间的共性，研究分子结构功能及进化关系，阐明一组相关序列的重要生物学模式。通过多序列比对可发现与结构域或功能相关的保守序列片段，发现蛋白质序列之间的系统发育关系。", "kp": "ch03_s0_0"}, {"id": "ch03_short_5", "modI": 0, "q": "简述Clustal工具的多序列比对流程。", "a": "Clustal采用渐进式算法。首先进行所有序列的两两比对构建距离矩阵；然后根据距离矩阵构建指导树；最后按照指导树的分支顺序进行渐进式比对。可对核酸和蛋白质序列进行多序列比对，输出结果可用于系统发育分析、保守区域识别等。", "kp": "ch03_s0_16"}], "calc": [{"id": "ch03_calc_1", "modI": 0, "q": "论述动态规划算法与BLAST算法在序列比对中的优缺点及适用场景。", "a": "动态规划算法是最精确的序列比对算法，分为全局动态规划算法（Needleman-Wunsch）和局部动态规划算法（Smith-Waterman）。优点是比对非常精确，缺点是运行时间长，不适合数据量庞大的序列数据库搜索。BLAST算法由Altschul等于1990年提出，采用短片段匹配算法和有效统计模型找出目的序列和数据库之间的最佳局部比对效果，基本思想是通过产生数量更少但质量更好的增强点来提高速度。BLAST是近似算法，速度快且比较精确。动态规划适用于较少量序列之间比对，BLAST适用于从大量序列中搜索相似序列。", "steps": "1. 动态规划算法精确但慢；2. BLAST近似但快；3. 动态规划适合少量序列；4. BLAST适合大规模数据库搜索。", "kp": "ch03_s0_11"}, {"id": "ch03_calc_2", "modI": 0, "q": "分析多序列比对中渐进式算法、迭代算法和统计概率算法的基本思想及特点。", "a": "渐进式算法是大多数多序列比对工具采用的算法，基本思想基于相似序列通常具有进化相关性假设：首先进行双序列比对构建距离矩阵；然后进行指导树构建；最后进行渐进式比对，对关系密切的序列加权，从最紧密两条序列开始逐步引入邻近序列并不断重新构建比对，直到所有序列加入。迭代算法核心是使用比对记分函数反复添加附加序列到已知比对中。统计概率算法常用隐马尔可夫模型（HMM），描述大量相互联系状态之间发生转换概率的模型，本质上是一条表示匹配、缺失或插入状态的链，用于检测序列比对结果中的保守区。", "steps": "1. 渐进式：距离矩阵→指导树→渐进比对；2. 迭代：反复添加序列优化；3. 统计概率：HMM描述状态转换；4. 各有优缺点，适用于不同规模和数据。", "kp": "ch03_s0_15"}], "term": [{"id": "ch03_term_1", "modI": 0, "term": "Sequence Alignment", "def": "定义：运用特定数学模型或算法，找出两个或多个序列之间的最大匹配碱基或残基数，反映序列间相似性关系及生物学特征。\n要点：\n- 是序列分析和数据库搜索的基础。\n- 可用于寻找保守基序、判定同源性、预测新基因功能。\n- 双序列比对比较两条序列的相似区域和保守位点，寻找分子进化关系。\n- 多序列比对寻找共同保守区域、位点和模式，探索共同功能的序列模式。\n- 可将蛋白质序列与核酸序列比较以探索表达框架，或与三维结构蛋白质比较获得结构折叠信息。", "kp": "ch03_s0_0"}, {"id": "ch03_term_2", "modI": 0, "term": "Global Alignment", "def": "定义：考虑序列的全局相似性，对给定序列全长进行比较，引入空位使全长都得到比较。\n要点：\n- 适用于高度同源序列的优化。\n- 常用于以已知三维结构同源序列为基础进行结构预测。\n- 经典算法为Needleman-Wunsch算法。\n- 最佳路径终点在得分矩阵最后一行最后一列。", "kp": "ch03_s0_1"}, {"id": "ch03_term_3", "modI": 0, "term": "Local Alignment", "def": "定义：仅获得特定序列在数据库中配对最好的亚区，考虑序列片段之间的相似性。\n要点：\n- 用于发现两条序列局部水平上的相似性。\n- 经典算法为Smith-Waterman算法。\n- 最佳路径终点在得分矩阵中元素值最大的位置。\n- 适合寻找保守结构域或功能基序。", "kp": "ch03_s0_1"}, {"id": "ch03_term_4", "modI": 0, "term": "Edit Distance", "def": "定义：通过编辑操作将一个序列转化为另一个序列所需的最小操作代价或距离。\n要点：\n- 编辑操作包括Match、Delete、Replace、Insert。\n- 用字符“-”代表空位。\n- 一条序列中的删除等价于另一条序列对应位置上的插入。\n- 两个空位字符不能匹配。\n- 最小编辑距离应在给定代价函数或得分函数下计算。", "kp": "ch03_s0_2"}, {"id": "ch03_term_5", "modI": 0, "term": "Scoring Matrix", "def": "定义：序列比较的基础，为不同字符替换赋予得分或代价的矩阵。\n要点：\n- 选择不同打分矩阵将得到不同比较结果。\n- 只考虑残基同一性的矩阵为稀疏矩阵，相同残基打1分、不同残基打0分。\n- 蛋白质序列常用PAM矩阵和BLOSUM矩阵。\n- 核酸序列可区分转换与颠换，也可使用单位矩阵或概率矩阵。", "kp": "ch03_s0_6"}, {"id": "ch03_term_6", "modI": 0, "term": "PAM Matrix", "def": "定义：Dayhoff基于突变数据提出的氨基酸替换打分矩阵。\n要点：\n- 全称Point Accepted Mutation矩阵。\n- 基于自然界中氨基酸残基的相互替换率统计。\n- 1个PAM单位表示每100个氨基酸残基中发生1次可接受突变。\n- 常用于蛋白质序列比对和数据库搜索。", "kp": "ch03_s0_8"}, {"id": "ch03_term_7", "modI": 0, "term": "BLOSUM Matrix", "def": "定义：基于Blocks数据库统计得到的氨基酸替换打分矩阵。\n要点：\n- 全称BLOcks SUbstitution Matrix。\n- 常用BLOSUM62作为BLAST默认矩阵。\n- 基于保守区块中氨基酸替换频率统计。\n- 与PAM矩阵同为蛋白质序列比对常用打分矩阵。", "kp": "ch03_s0_8"}, {"id": "ch03_term_8", "modI": 0, "term": "Dotplot", "def": "定义：最古老的序列比对算法之一，通过点阵作图方法直观表示两条序列之间的相似性。\n要点：\n- 将两条序列分别沿x轴和y轴排列，相同字符处填充点。\n- 对角线方向相邻点连接形成相似性片段。\n- 获得的相似性片段实际上是相同片段，不能提供统计学意义上的相似性。\n- 在线工具如Dotlet可创建点阵矩阵。", "kp": "ch03_s0_9"}, {"id": "ch03_term_9", "modI": 0, "term": "Needleman-Wunsch Algorithm", "def": "定义：经典全局动态规划算法，由Needleman和Wunsch于1970年提出。\n要点：\n- 用于发现两条序列全局水平上的相似性。\n- 计算得分矩阵，使用迭代方法计算相似分值。\n- 根据得分矩阵从最佳路径终点利用回溯法寻找最优路径。\n- 最佳路径终点在最后一行最后一列。", "kp": "ch03_s0_10"}, {"id": "ch03_term_10", "modI": 0, "term": "Smith-Waterman Algorithm", "def": "定义：经典局部动态规划算法，由Smith和Waterman于1981年提出。\n要点：\n- 用于发现两条序列局部水平上的相似性。\n- 计算得分矩阵方法与Needleman-Wunsch相同。\n- 最佳路径终点在元素值最大的位置。\n- 适合寻找局部相似区域或保守基序。", "kp": "ch03_s0_10"}, {"id": "ch03_term_11", "modI": 0, "term": "BLAST", "def": "定义：Basic Local Alignment Search Tool，由Altschul等于1990年提出，采用短片段匹配算法和有效统计模型找出目的序列和数据库之间的最佳局部比对效果。\n要点：\n- 基本思想是通过产生数量更少但质量更好的增强点来提高速度。\n- 步骤包括编译字段列表、扫描数据库匹配、延伸寻找高分值片段对（HSP）。\n- E值表示随机条件下期望发生的得分大于S的不同比对数目，用于估计假阳性。\n- 是近似算法，速度快且比较精确，适用于从大量序列中搜索相似序列。", "kp": "ch03_s0_11"}, {"id": "ch03_term_12", "modI": 0, "term": "Multiple Sequence Alignment", "def": "定义：对3条以上（包括3条）序列进行的比对，插入空位使全局比对结果具有相同长度，且不能出现一列全为空位。\n要点：\n- 目的为发现同一基因家族成组序列之间的共性。\n- 可发现与结构域或功能相关的保守序列片段。\n- 可发现蛋白质序列之间的系统发育关系。\n- 应用于发现新序列与已知序列家族的同源性、蛋白质二级和三级结构预测等。", "kp": "ch03_s0_0"}]}], "mcq": [{"id": "ch03_mcq_1", "mod": "第三章 序列比对原理", "modI": 0, "q": "关于序列比对中全局比对与局部比对的描述，正确的是：", "o": ["A. 全局比对仅比较序列片段之间的相似性，局部比对比较序列全长", "B. 全局比对考虑序列的全局相似性，局部比对考虑序列片段之间的相似性", "C. 全局比对和局部比对都只考虑序列的局部相似性", "D. 全局比对适用于寻找保守基序，局部比对适用于高度同源序列优化"], "a": "B", "e": "全局比对（global alignment）考虑序列的全局相似性，对给定序列全长进行比较；局部比对（local alignment）考虑序列片段之间的相似性，仅获得特定序列在数据库中配对最好的亚区。A项颠倒，C项错误，D项中全局比对适用于高度同源序列优化，局部比对适用于寻找保守片段。", "kp": "ch03_s0_1"}, {"id": "ch03_mcq_2", "mod": "第三章 序列比对原理", "modI": 0, "q": "在序列比对中，字符编辑操作Replace(a,b)的含义是：", "o": ["A. 从第一条序列删除一个字符a", "B. 在第一条序列插入空位字符", "C. 以第二条序列中的字符b替换第一条序列中的字符a", "D. 字符a与字符b匹配"], "a": "C", "e": "Replace(a,b)表示以第二条序列中的字符b替换第一条序列中的字符a。Delete(a,-)表示从第一条序列删除一个字符a或在第二条序列相应位置插入空位；Insert(-,b)表示在第一条序列插入空位字符或删除第二条序列中对应字符b；Match(a,a)表示字符匹配。", "kp": "ch03_s0_2"}, {"id": "ch03_mcq_3", "mod": "第三章 序列比对原理", "modI": 0, "q": "关于直系同源基因和旁系同源基因，下列说法正确的是：", "o": ["A. 直系同源基因是一个物种内的同源基因，旁系同源基因是不同物种中的同源基因", "B. 直系同源基因是在物种形成过程中形成的，旁系同源基因是种内基因倍增的结果", "C. 直系同源基因和旁系同源基因都一定具有相同的生物学功能", "D. 直系同源基因由基因倍增产生，旁系同源基因由物种形成产生"], "a": "B", "e": "直系同源基因（orthologous gene）指不同物种中有相同功能的同源基因，在物种形成过程中形成；旁系同源基因（paralogous gene）指一个物种内的同源基因，是种内基因倍增的结果。A项颠倒，C项旁系同源一般有相似但并不相同的功能，D项颠倒。", "kp": "ch03_s0_5"}, {"id": "ch03_mcq_4", "mod": "第三章 序列比对原理", "modI": 0, "q": "关于DNA序列比对中的转换和颠换，下列描述正确的是：", "o": ["A. 转换是指嘌呤被嘧啶替换，如A→C", "B. 颠换是指同类核苷酸替换，如A→G", "C. 转换是指同类核苷酸替换，如A→G；颠换是指嘌呤被嘧啶替换或反之，如A→C", "D. 转换和颠换在打分矩阵中总是给予相同评分"], "a": "C", "e": "转换（transition）指同类核苷酸替换，如A→G、C→T；颠换（transversion）指嘌呤被嘧啶替换或反之，如A→C、G→T。可对核苷酸的颠换与转换给予不同评分，因为转换比颠换更常见。", "kp": "ch03_s0_7"}, {"id": "ch03_mcq_5", "mod": "第三章 序列比对原理", "modI": 0, "q": "关于dotplot算法，下列说法错误的是：", "o": ["A. dotplot算法是最古老的序列比对算法，通过点阵作图方法表示", "B. 在点阵矩阵中，将位于对角线方向上相邻的点连接起来可获得相似性片段", "C. dotplot算法能提供相似片段在统计学意义上的相似性", "D. dotplot算法获得的相似性片段实际上是相同片段"], "a": "C", "e": "dotplot算法由于算法思想所限，获得的相似性片段实际上是相同片段，而且不能提供相似片段在统计学意义上的相似性。A、B、D描述正确。", "kp": "ch03_s0_9"}, {"id": "ch03_mcq_6", "mod": "第三章 序列比对原理", "modI": 0, "q": "关于动态规划算法，下列描述正确的是：", "o": ["A. Needleman-Wunsch算法用于局部比对，Smith-Waterman算法用于全局比对", "B. Needleman-Wunsch算法由Smith和Waterman于1981年提出", "C. 全局动态规划算法最佳路径终点在最后一行最后一列，局部动态规划算法最佳路径终点在元素值最大的位置", "D. 动态规划算法运行时间短，适合大规模数据库搜索"], "a": "C", "e": "Needleman-Wunsch算法由Needleman和Wunsch于1970年提出，用于全局比对；Smith-Waterman算法由Smith和Waterman于1981年提出，用于局部比对。全局动态规划算法最佳路径终点在最后一行最后一列，局部动态规划算法最佳路径终点在元素值最大的位置。动态规划算法优点是精确，缺点是运行时间长，不适合大规模数据库搜索。", "kp": "ch03_s0_10"}, {"id": "ch03_mcq_7", "mod": "第三章 序列比对原理", "modI": 0, "q": "关于BLAST算法，下列说法正确的是：", "o": ["A. BLAST算法是一种精确算法，运行时间比动态规划算法长", "B. BLAST算法由Altschul等在1990年提出，采用短片段匹配算法和统计模型", "C. BLAST算法中E值越小表示假阳性结果越多", "D. BLAST算法适用于较少量序列之间的精确比对"], "a": "B", "e": "BLAST算法由Altschul等在1990年提出，采用短片段匹配算法和有效统计模型找出最佳局部比对效果，基本思想是通过产生数量更少但质量更好的增强点来提高速度。BLAST是近似算法，速度快且比较精确，适用于从大量序列中搜索相似序列。E值表示随机条件下期望发生的得分大于S的不同比对数目，E值越小表示假阳性结果越少。", "kp": "ch03_s0_11"}, {"id": "ch03_mcq_8", "mod": "第三章 序列比对原理", "modI": 0, "q": "BLAST工具中，将DNA序列用所有可能阅读框翻译成6个蛋白质，然后逐一与蛋白质数据库进行比较的程序是：", "o": ["A. blastn", "B. blastp", "C. blastx", "D. tblastn"], "a": "C", "e": "blastx将DNA序列用所有可能的阅读框翻译成6个蛋白质，然后将它们逐一与蛋白质数据库进行比较。blastn将DNA查询序列与DNA数据库比较；blastp将蛋白质查询序列与蛋白质数据库比较；tblastn将DNA数据库中每条序列翻译成6种可能蛋白质后与查询蛋白质序列比较。", "kp": "ch03_s0_13"}, {"id": "ch03_mcq_9", "mod": "第三章 序列比对原理", "modI": 0, "q": "关于多序列比对，下列说法错误的是：", "o": ["A. 多序列比对是对3条以上（包括3条）序列进行的比对", "B. 多序列比对结果中不能出现一列全为空位", "C. 渐进式算法是大多数多序列比对工具采用的算法", "D. 多序列比对只能用于发现保守序列片段，不能用于系统发育分析"], "a": "D", "e": "多序列比对可应用于发现新序列与已知序列家族的同源性、蛋白质序列二级和三级结构预测、发现蛋白之间系统发生关系、获取蛋白质家族中结构或功能相似片段等。A、B、C描述正确。渐进式算法基本思想基于相似序列通常具有进化相关性假设，是大多数多序列比对工具采用的算法。", "kp": "ch03_s0_1"}, {"id": "ch03_mcq_10", "mod": "第三章 序列比对原理", "modI": 0, "q": "关于隐马尔可夫模型（HMM）在多序列比对中的应用，下列说法正确的是：", "o": ["A. HMM本质上是一条仅表示匹配状态的链", "B. HMM用于多序列比对时，每个保守残基用匹配状态描述，空位插入用插入状态描述，残基缺失用缺失状态描述", "C. HMM不能用于检测序列比对结果中的保守区", "D. HMM是一种双序列比对算法"], "a": "B", "e": "HMM是描述大量相互联系状态之间发生转换概率的模型，本质上是一条表示匹配、缺失或插入状态的链。用于多序列比对计算时，可用来检测序列比对结果中的保守区。每个保守残基可用匹配状态描述，空位插入用插入状态描述，残基缺失状态表示允许在本该匹配的位置发生缺失。HMM是统计概率算法，用于多序列比对。", "kp": "ch03_s0_15"}], "judge": [{"id": "ch03_judge_1", "modI": 0, "q": "相似性高一定等于同源性。", "a": "错", "e": "相似性高并不等于同源性，但大多数情况下相似性可表明同源性。发现两个基因或蛋白质具有很高序列相似性时，推测它们具有共同进化历程，但推断成为结论前必须经过实验验证。", "kp": "ch03_s0_5"}, {"id": "ch03_judge_2", "modI": 0, "q": "直系同源基因指不同物种中有相同功能的同源基因，在物种形成过程中形成。", "a": "对", "e": "直系同源基因（orthologous gene）指不同物种中有相同功能的同源基因，在物种形成过程中形成。旁系同源基因指一个物种内的同源基因，是种内基因倍增的结果。", "kp": "ch03_s0_5"}, {"id": "ch03_judge_3", "modI": 0, "q": "两个空位字符可以匹配。", "a": "错", "e": "两个空位字符不能匹配。", "kp": "ch03_s0_2"}, {"id": "ch03_judge_4", "modI": 0, "q": "全局比对最佳路径终点在得分矩阵最后一行最后一列。", "a": "对", "e": "全局算法最佳路径终点在最后一行最后一列，局部算法最佳路径终点在元素值最大的位置。", "kp": "ch03_s0_10"}, {"id": "ch03_judge_5", "modI": 0, "q": "BLAST算法是精确算法，运行时间短。", "a": "错", "e": "BLAST是近似算法，速度快且比较精确。动态规划算法是最精确的序列比对算法，但运行时间长。", "kp": "ch03_s0_11"}, {"id": "ch03_judge_6", "modI": 0, "q": "FASTA工具与序列储存格式FASTA是同一概念。", "a": "错", "e": "FASTA是FAST-ALL的缩写，与序列储存格式FASTA无关，是一种可用于核酸和蛋白质序列的快速序列比对数据库搜索工具。", "kp": "ch03_s0_12"}, {"id": "ch03_judge_7", "modI": 0, "q": "ClustalX是命令行版本，ClustalW是图形界面版本。", "a": "错", "e": "ClustalX是图形界面版本，ClustalW是命令行版本。", "kp": "ch03_s0_16"}, {"id": "ch03_judge_8", "modI": 0, "q": "多序列比对结果中不能出现一列全为空位。", "a": "对", "e": "多序列比对定义：对多条序列插入空位，使得插入空位后的全局比对结果具有相同长度，并且比对结果中不能出现一列全为空位。", "kp": "ch03_s0_14"}, {"id": "ch03_judge_9", "modI": 0, "q": "dotplot算法能提供相似片段在统计学意义上的相似性。", "a": "错", "e": "由于算法思想所限，dotplot算法获得的相似性片段实际上是相同片段，不能提供相似片段在统计学意义上的相似性。", "kp": "ch03_s0_9"}, {"id": "ch03_judge_10", "modI": 0, "q": "BLAST中，tblastx将查询DNA及数据库DNA都翻译成6种可能蛋白质后进行36次蛋白质-蛋白质数据库搜索。", "a": "对", "e": "tblastx将查询DNA及数据库DNA都翻译成6种可能蛋白质后进行36次蛋白质-蛋白质数据库搜索。", "kp": "ch03_s0_13"}], "fill": [{"id": "ch03_fill_1", "modI": 0, "q": "序列比对中，全局比对经典算法为________，局部比对经典算法为________。", "a": "Needleman-Wunsch,Smith-Waterman", "kp": "ch03_s0_1"}, {"id": "ch03_fill_2", "modI": 0, "q": "在编辑操作中，用字符“________”代表空位。", "a": "-", "kp": "ch03_s0_2"}, {"id": "ch03_fill_3", "modI": 0, "q": "蛋白质序列比对常用的打分矩阵包括________和________。", "a": "PAM,BLOSUM", "kp": "ch03_s0_16"}, {"id": "ch03_fill_4", "modI": 0, "q": "BLAST工具中，________将DNA查询序列不同方向两条链与DNA数据库比较。", "a": "blastn", "kp": "ch03_s0_13"}, {"id": "ch03_fill_5", "modI": 0, "q": "BLAST工具中，________将DNA序列用所有可能阅读框翻译成6个蛋白质后逐一与蛋白质数据库比较。", "a": "blastx", "kp": "ch03_s0_13"}, {"id": "ch03_fill_6", "modI": 0, "q": "多序列比对渐进式算法中，首先进行双序列比对构建________，然后构建________，最后进行渐进式比对。", "a": "距离矩阵,指导树", "kp": "ch03_s0_15"}, {"id": "ch03_fill_7", "modI": 0, "q": "Clustal工具采用________算法进行多序列比对。", "a": "渐进式", "kp": "ch03_s0_16"}, {"id": "ch03_fill_8", "modI": 0, "q": "BLAST中，E值表示数据库搜索中随机条件下期望发生的得分大于S的不同比对数目，用于估计________结果。", "a": "假阳性", "kp": "ch03_s0_11"}], "short": [{"id": "ch03_short_1", "modI": 0, "q": "简述序列比对的生物学意义。", "a": "序列比对是序列分析和数据库搜索的基础。可用于寻找保守基序、判定同源性、预测新基因功能。双序列比对比较两条序列的相似区域和保守位点，寻找分子进化关系；多序列比对寻找共同保守区域、位点和模式，探索共同功能的序列模式。还可将蛋白质序列与核酸序列比较以探索表达框架，或与三维结构蛋白质比较获得结构折叠信息。", "kp": "ch03_s0_0"}, {"id": "ch03_short_2", "modI": 0, "q": "简述全局比对与局部比对的区别。", "a": "全局比对考虑序列的全局相似性，对给定序列全长进行比较，引入空位使全长都得到比较，适用于高度同源序列的优化，如以已知三维结构同源序列为基础进行结构预测。局部比对仅获得特定序列在数据库中配对最好的亚区，考虑序列片段之间的相似性。全局比对经典算法为Needleman-Wunsch，局部比对经典算法为Smith-Waterman。", "kp": "ch03_s0_1"}, {"id": "ch03_short_3", "modI": 0, "q": "简述BLAST算法的基本步骤。", "a": "1. 编译一个由查询序列生成的长度固定的字段编译列表；2. 在数据库中扫描获得与编译列表字段匹配的序列记录；3. 以编译列表中的字段对为中心向两端延伸以寻找超过阈值分数S的高分值片段对（HSP）。BLAST是近似算法，速度快且比较精确。", "kp": "ch03_s0_11"}, {"id": "ch03_short_4", "modI": 0, "q": "简述多序列比对的定义与目的。", "a": "定义：对3条以上（包括3条）序列插入空位，使得插入空位后的全局比对结果具有相同长度，并且比对结果中不能出现一列全为空位。目的：发现构成同一基因家族的成组序列之间的共性，研究分子结构功能及进化关系，阐明一组相关序列的重要生物学模式。通过多序列比对可发现与结构域或功能相关的保守序列片段，发现蛋白质序列之间的系统发育关系。", "kp": "ch03_s0_0"}, {"id": "ch03_short_5", "modI": 0, "q": "简述Clustal工具的多序列比对流程。", "a": "Clustal采用渐进式算法。首先进行所有序列的两两比对构建距离矩阵；然后根据距离矩阵构建指导树；最后按照指导树的分支顺序进行渐进式比对。可对核酸和蛋白质序列进行多序列比对，输出结果可用于系统发育分析、保守区域识别等。", "kp": "ch03_s0_16"}], "calc": [{"id": "ch03_calc_1", "modI": 0, "q": "论述动态规划算法与BLAST算法在序列比对中的优缺点及适用场景。", "a": "动态规划算法是最精确的序列比对算法，分为全局动态规划算法（Needleman-Wunsch）和局部动态规划算法（Smith-Waterman）。优点是比对非常精确，缺点是运行时间长，不适合数据量庞大的序列数据库搜索。BLAST算法由Altschul等于1990年提出，采用短片段匹配算法和有效统计模型找出目的序列和数据库之间的最佳局部比对效果，基本思想是通过产生数量更少但质量更好的增强点来提高速度。BLAST是近似算法，速度快且比较精确。动态规划适用于较少量序列之间比对，BLAST适用于从大量序列中搜索相似序列。", "steps": "1. 动态规划算法精确但慢；2. BLAST近似但快；3. 动态规划适合少量序列；4. BLAST适合大规模数据库搜索。", "kp": "ch03_s0_11"}, {"id": "ch03_calc_2", "modI": 0, "q": "分析多序列比对中渐进式算法、迭代算法和统计概率算法的基本思想及特点。", "a": "渐进式算法是大多数多序列比对工具采用的算法，基本思想基于相似序列通常具有进化相关性假设：首先进行双序列比对构建距离矩阵；然后进行指导树构建；最后进行渐进式比对，对关系密切的序列加权，从最紧密两条序列开始逐步引入邻近序列并不断重新构建比对，直到所有序列加入。迭代算法核心是使用比对记分函数反复添加附加序列到已知比对中。统计概率算法常用隐马尔可夫模型（HMM），描述大量相互联系状态之间发生转换概率的模型，本质上是一条表示匹配、缺失或插入状态的链，用于检测序列比对结果中的保守区。", "steps": "1. 渐进式：距离矩阵→指导树→渐进比对；2. 迭代：反复添加序列优化；3. 统计概率：HMM描述状态转换；4. 各有优缺点，适用于不同规模和数据。", "kp": "ch03_s0_15"}], "term": [{"id": "ch03_term_1", "modI": 0, "term": "Sequence Alignment", "def": "定义：运用特定数学模型或算法，找出两个或多个序列之间的最大匹配碱基或残基数，反映序列间相似性关系及生物学特征。\n要点：\n- 是序列分析和数据库搜索的基础。\n- 可用于寻找保守基序、判定同源性、预测新基因功能。\n- 双序列比对比较两条序列的相似区域和保守位点，寻找分子进化关系。\n- 多序列比对寻找共同保守区域、位点和模式，探索共同功能的序列模式。\n- 可将蛋白质序列与核酸序列比较以探索表达框架，或与三维结构蛋白质比较获得结构折叠信息。", "kp": "ch03_s0_0"}, {"id": "ch03_term_2", "modI": 0, "term": "Global Alignment", "def": "定义：考虑序列的全局相似性，对给定序列全长进行比较，引入空位使全长都得到比较。\n要点：\n- 适用于高度同源序列的优化。\n- 常用于以已知三维结构同源序列为基础进行结构预测。\n- 经典算法为Needleman-Wunsch算法。\n- 最佳路径终点在得分矩阵最后一行最后一列。", "kp": "ch03_s0_1"}, {"id": "ch03_term_3", "modI": 0, "term": "Local Alignment", "def": "定义：仅获得特定序列在数据库中配对最好的亚区，考虑序列片段之间的相似性。\n要点：\n- 用于发现两条序列局部水平上的相似性。\n- 经典算法为Smith-Waterman算法。\n- 最佳路径终点在得分矩阵中元素值最大的位置。\n- 适合寻找保守结构域或功能基序。", "kp": "ch03_s0_1"}, {"id": "ch03_term_4", "modI": 0, "term": "Edit Distance", "def": "定义：通过编辑操作将一个序列转化为另一个序列所需的最小操作代价或距离。\n要点：\n- 编辑操作包括Match、Delete、Replace、Insert。\n- 用字符“-”代表空位。\n- 一条序列中的删除等价于另一条序列对应位置上的插入。\n- 两个空位字符不能匹配。\n- 最小编辑距离应在给定代价函数或得分函数下计算。", "kp": "ch03_s0_2"}, {"id": "ch03_term_5", "modI": 0, "term": "Scoring Matrix", "def": "定义：序列比较的基础，为不同字符替换赋予得分或代价的矩阵。\n要点：\n- 选择不同打分矩阵将得到不同比较结果。\n- 只考虑残基同一性的矩阵为稀疏矩阵，相同残基打1分、不同残基打0分。\n- 蛋白质序列常用PAM矩阵和BLOSUM矩阵。\n- 核酸序列可区分转换与颠换，也可使用单位矩阵或概率矩阵。", "kp": "ch03_s0_6"}, {"id": "ch03_term_6", "modI": 0, "term": "PAM Matrix", "def": "定义：Dayhoff基于突变数据提出的氨基酸替换打分矩阵。\n要点：\n- 全称Point Accepted Mutation矩阵。\n- 基于自然界中氨基酸残基的相互替换率统计。\n- 1个PAM单位表示每100个氨基酸残基中发生1次可接受突变。\n- 常用于蛋白质序列比对和数据库搜索。", "kp": "ch03_s0_8"}, {"id": "ch03_term_7", "modI": 0, "term": "BLOSUM Matrix", "def": "定义：基于Blocks数据库统计得到的氨基酸替换打分矩阵。\n要点：\n- 全称BLOcks SUbstitution Matrix。\n- 常用BLOSUM62作为BLAST默认矩阵。\n- 基于保守区块中氨基酸替换频率统计。\n- 与PAM矩阵同为蛋白质序列比对常用打分矩阵。", "kp": "ch03_s0_8"}, {"id": "ch03_term_8", "modI": 0, "term": "Dotplot", "def": "定义：最古老的序列比对算法之一，通过点阵作图方法直观表示两条序列之间的相似性。\n要点：\n- 将两条序列分别沿x轴和y轴排列，相同字符处填充点。\n- 对角线方向相邻点连接形成相似性片段。\n- 获得的相似性片段实际上是相同片段，不能提供统计学意义上的相似性。\n- 在线工具如Dotlet可创建点阵矩阵。", "kp": "ch03_s0_9"}, {"id": "ch03_term_9", "modI": 0, "term": "Needleman-Wunsch Algorithm", "def": "定义：经典全局动态规划算法，由Needleman和Wunsch于1970年提出。\n要点：\n- 用于发现两条序列全局水平上的相似性。\n- 计算得分矩阵，使用迭代方法计算相似分值。\n- 根据得分矩阵从最佳路径终点利用回溯法寻找最优路径。\n- 最佳路径终点在最后一行最后一列。", "kp": "ch03_s0_10"}, {"id": "ch03_term_10", "modI": 0, "term": "Smith-Waterman Algorithm", "def": "定义：经典局部动态规划算法，由Smith和Waterman于1981年提出。\n要点：\n- 用于发现两条序列局部水平上的相似性。\n- 计算得分矩阵方法与Needleman-Wunsch相同。\n- 最佳路径终点在元素值最大的位置。\n- 适合寻找局部相似区域或保守基序。", "kp": "ch03_s0_10"}, {"id": "ch03_term_11", "modI": 0, "term": "BLAST", "def": "定义：Basic Local Alignment Search Tool，由Altschul等于1990年提出，采用短片段匹配算法和有效统计模型找出目的序列和数据库之间的最佳局部比对效果。\n要点：\n- 基本思想是通过产生数量更少但质量更好的增强点来提高速度。\n- 步骤包括编译字段列表、扫描数据库匹配、延伸寻找高分值片段对（HSP）。\n- E值表示随机条件下期望发生的得分大于S的不同比对数目，用于估计假阳性。\n- 是近似算法，速度快且比较精确，适用于从大量序列中搜索相似序列。", "kp": "ch03_s0_11"}, {"id": "ch03_term_12", "modI": 0, "term": "Multiple Sequence Alignment", "def": "定义：对3条以上（包括3条）序列进行的比对，插入空位使全局比对结果具有相同长度，且不能出现一列全为空位。\n要点：\n- 目的为发现同一基因家族成组序列之间的共性。\n- 可发现与结构域或功能相关的保守序列片段。\n- 可发现蛋白质序列之间的系统发育关系。\n- 应用于发现新序列与已知序列家族的同源性、蛋白质二级和三级结构预测等。", "kp": "ch03_s0_0"}], "preview": {"main": "本章围绕序列比对的基本概念、编辑操作与打分函数、双序列比对算法（dotplot、Needleman-Wunsch、Smith-Waterman）、数据库搜索工具（BLAST、FASTA）、打分矩阵（PAM、BLOSUM）以及多序列比对（渐进式、迭代、HMM、Clustal）展开，核心是理解如何用算法和统计模型判断序列相似性、同源性与功能关系。", "questions": ["序列比对中全局比对与局部比对的核心区别是什么？各自适用于什么场景？", "编辑距离、打分函数与最优比对之间是什么关系？为什么说最优比对依赖于所选的打分方案？", "Needleman-Wunsch和Smith-Waterman算法在动态规划递推、初始化与回溯终点上有何异同？", "BLAST和FASTA如何加速数据库搜索？E值和HSP在结果解读中起什么作用？", "多序列比对为什么重要？渐进式算法、迭代算法和基于HMM的统计概率算法各自解决什么问题？"]}, "appcards": [{"front": "应用/分析题：给定两条长度不同的蛋白质序列，如何判断应使用全局比对还是局部比对？并说明两种比对在动态规划实现上的关键差异。", "back": "若两条序列整体高度同源、长度相近，且需要比较全长（如以已知三维结构同源序列为基础进行结构预测），应使用全局比对（Needleman-Wunsch）。若只关心局部保守区域、结构域或模体，或两条序列仅部分区域相似，应使用局部比对（Smith-Waterman）。关键差异：全局比对得分矩阵初始化时首行首列按空位罚分累加，最优路径终点在最后一行最后一列；局部比对得分矩阵初始化首行首列为0，且递推中允许得分小于0时取0，最优路径终点为矩阵中得分最大的元素。", "points": "全局比对适用条件；局部比对适用条件；Needleman-Wunsch；Smith-Waterman；初始化差异；终点位置差异；回溯法", "mod": 0, "modName": "第三章 序列比对原理", "level": "掌握", "src": "生成"}, {"front": "应用/分析题：为什么蛋白质序列比对通常需要PAM或BLOSUM等打分矩阵，而不能简单使用相同残基得1分、不同残基得0分的稀疏矩阵？", "back": "蛋白质由20种氨基酸组成，不同氨基酸残基的理化性质、保守替换概率和进化可接受性差异很大。保守替换（如理化性质相近的氨基酸之间）通常比随机替换更可能维持蛋白质结构与功能，因此应给予不同得分。稀疏矩阵只考虑同一性，忽略同类替换与非同类替换的差别，信息量少、区分能力弱，容易低估真实同源关系。PAM矩阵基于Dayhoff突变数据，BLOSUM矩阵基于局部比对中氨基酸替换频率，能反映自然界中氨基酸替换倾向，因此更适合蛋白质序列比对。", "points": "20种氨基酸复杂性；保守替换；理化性质；稀疏矩阵局限；PAM；BLOSUM；Dayhoff；替换频率", "mod": 0, "modName": "第三章 序列比对原理", "level": "掌握", "src": "生成"}, {"front": "应用/分析题：在NCBI BLAST网页或命令行中，若要用DNA查询序列搜索蛋白质数据库，应选择哪个BLAST程序？若要用蛋白质查询序列搜索翻译后的DNA数据库，应选择哪个？并解释E值含义。", "back": "DNA查询序列搜索蛋白质数据库应选择blastx：将DNA序列按所有可能阅读框翻译成6个蛋白质序列后逐一与蛋白质数据库比较。蛋白质查询序列搜索翻译后的DNA数据库应选择tblastn：将DNA数据库中每条序列翻译成6种可能蛋白质后与查询蛋白质序列比较。E值表示在给定数据库大小和随机条件下，期望发生的得分不低于观察得分S的不同比对数目，用于估计假阳性；E值越小，比对越可靠。", "points": "blastx；tblastn；6个阅读框；翻译；E值；随机期望；假阳性；数据库搜索", "mod": 0, "modName": "第三章 序列比对原理", "level": "掌握", "src": "生成"}, {"front": "应用/分析题：多序列比对中渐进式算法的主要步骤是什么？以Clustal为例说明其流程，并指出该方法可能存在的局限。", "back": "渐进式算法基于相似序列通常具有进化相关性的假设。主要步骤：1. 对所有序列进行两两双序列比对，构建距离矩阵；2. 根据距离矩阵构建指导树（guide tree）；3. 按指导树分支顺序，从关系最紧密的两条序列开始逐步加入邻近序列，进行渐进式比对，直至所有序列加入。Clustal（如ClustalW/ClustalX）采用该策略：先两两比对建距离矩阵，再建指导树，最后按树顺序渐进比对。局限：早期比对中引入的空位和错误会在后续步骤中被固定，无法通过后续迭代纠正，因此结果可能依赖序列加入顺序，对差异较大的序列集合可能不够准确。", "points": "渐进式算法；距离矩阵；指导树；ClustalW/ClustalX；逐步加入；空位固定；顺序依赖；局限", "mod": 0, "modName": "第三章 序列比对原理", "level": "掌握", "src": "生成"}, {"front": "应用/分析题：解释直系同源基因与旁系同源基因的区别。为什么仅凭序列相似性不能直接断定同源性或功能相同？", "back": "同源基因指来自共同祖先的基因。直系同源基因（orthologous gene）是不同物种中由物种形成事件产生的同源基因，通常具有相同或相似功能。旁系同源基因（paralogous gene）是同一物种内由基因倍增产生的同源基因，功能一般相似但不完全相同。序列相似性高并不等于同源性；相似性可能来自趋同进化、低复杂度区域或数据库污染等。即使推断为同源，也不能直接断定功能相同，必须经过实验验证。实践中仅从序列信息区分直系同源与旁系同源并不容易，常需结合系统发育分析和基因组上下文。", "points": "同源基因；直系同源；旁系同源；物种形成；基因倍增；相似性不等于同源性；功能需实验验证；系统发育", "mod": 0, "modName": "第三章 序列比对原理", "level": "掌握", "src": "生成"}, {"front": "应用/分析题：dotplot算法与动态规划算法在序列比对中的定位有何不同？BLAST与动态规划相比为何适合数据库搜索？", "back": "dotplot是最古老的序列比对可视化方法，将两条序列分别置于x轴和y轴，相同碱基或残基处打点，对角线上的连续点表示相似片段。它直观显示重复、倒位和相似区域，但只能反映相同片段，不能提供统计学显著性，也不能直接给出最优比对。动态规划（Needleman-Wunsch/Smith-Waterman）是最精确的比对算法，能保证在给定打分函数下找到最优全局或局部比对，但时间复杂度高，不适合大规模数据库搜索。BLAST采用短片段匹配、字段编译列表、高分值片段对（HSP）延伸和有效统计模型，以E值评估显著性，速度远快于动态规划，适合从大量序列中搜索相似序列，但属于近似算法。", "points": "dotplot；点阵矩阵；对角线；可视化；动态规划；精确；时间复杂度；BLAST；短片段匹配；HSP；E值；近似算法；数据库搜索", "mod": 0, "modName": "第三章 序列比对原理", "level": "掌握", "src": "生成"}]};